window.BLOG_ARTICLE_CONTENT = window.BLOG_ARTICLE_CONTENT || {};
window.BLOG_ARTICLE_CONTENT["en/embodied-agent-papers"] = {"body": "\n<aside aria-label=\"Translation status\" class=\"translation-note\">\n<p>English translation of the <a data-local-language=\"zh\" href=\"#/post/embodied-agent-papers\" lang=\"zh-CN\">Chinese article</a> revised 2026-10-04. Translation updated 2026-10-04.</p>\n<p>Companion articles labeled <span class=\"language-label\">Chinese only</span> are available in Chinese. English editions will be added as they are completed.</p>\n</aside>\n<blockquote>\n<p>This collection accompanies <a data-local-language=\"en\" href=\"#/post/ai-agent-survey\">AI Agents: A Survey</a> and the architecture guide <a data-local-language=\"en\" href=\"#/post/embodied-agent-harness-survey\">Embodied Agents: Harness and Runtime Architecture</a>. It provides detailed readings of representative embodied-agent papers and recent advances.</p>\n</blockquote>\n<h1 id=\"具身智能体论文精读\">Embodied Agents: Paper Readings</h1>\n<p>This article focuses on a common problem: how robots organize perception, planning, execution, verification, and recovery into a closed-loop that can sustainably operate. The eight papers respectively start from the runtime, orchestrator, evaluator, evolution mechanism, action interface, training target, general AgentOS and inspection system governance. The experiments cover simulation environment, text interaction environment and real robots.</p>\n<table>\n<thead>\n<tr>\n<th>Paper</th>\n<th>Main entry points</th>\n<th>representative verification</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><a href=\"#holoagent-0\">HoloAgent-0</a></td>\n<td>AgentOS, typed skills and hierarchical Spatial memory</td>\n<td>HM3D, ScanNet, real heterogeneous robots</td>\n</tr>\n<tr>\n<td><a href=\"#pigey\">Pigey</a></td>\n<td>inference time physical orchestration, TAMP/VLA dual backend and double verification</td>\n<td>LIBERO-PRO, DROID real robot</td>\n</tr>\n<tr>\n<td><a href=\"#thea\">Thea</a></td>\n<td>Scene graph context and evaluator exit code</td>\n<td>L1–L3 long-horizon real robot tasks, cross-embodiment deployment</td>\n</tr>\n<tr>\n<td><a href=\"#zetta\">Zetta</a></td>\n<td>High-frequency judge, recovery action library and offline self-evolution</td>\n<td>LIBERO-Pro, concurrent sampling infrastructure</td>\n</tr>\n<tr>\n<td><a href=\"#show-harness\">Show-Harness</a></td>\n<td>Semantic action unit and embodiment interpreter</td>\n<td>Franka, AgileX, simulation and real robot generalization</td>\n</tr>\n<tr>\n<td><a href=\"#space\">SPACE</a></td>\n<td>Skill-guided adaptive action chunking and reinforcement learning</td>\n<td>ALFWorld, ScienceWorld</td>\n</tr>\n<tr>\n<td><a href=\"#abot-agentos\">ABot-AgentOS</a></td>\n<td>Dual LLM, Agent Harness, and Lifelong Multimodal Memory</td>\n<td>EmbodiedWorldBench, memory benchmark</td>\n</tr>\n<tr>\n<td><a href=\"#harness-robotic-os\">Harness Robotic OS</a></td>\n<td>Patrol runtime, hierarchical memory and self-evolution governance</td>\n<td>Real community navigation and inspection; cognitive operation needs to be controlled and verified</td>\n</tr>\n</tbody>\n</table>\n<p>The filter bar below supports multiple tag combinations; when multiple tags are selected at the same time, the page will only retain papers that meet these tags.</p>\n<div class=\"paper-filter-bar\" id=\"paper-filter-bar\"></div>\n<h2 id=\"holoagent-0\">1. HoloAgent-0 (2026)</h2>\n<p>——Unified embodied agent closed-loop operating system: decoupling heterogeneous physical skills, using layered 3D multi-modal Spatial memory as the physical anchor</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2606.23565\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2606.23565</a> · <a href=\"https://github.com/HorizonRobotics/HoloAgent\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a></p>\n<hr/>\n<h3 id=\"精华\">Key takeaways</h3>\n<ul>\n<li><strong>closed-loop embodied runtime architecture</strong>: Proposes the Embodied AgentOS operating system for physical robots, which reconstructs task planning from a single open-loop text generation to a continuous closed-loop of “observation-retrieval-action-monitoring”, effectively filling the execution uncertainty of the physical world.</li>\n<li><strong>Standardized Typed Skills Abstract (Typed Skills)</strong>: Developed action specifications including structured parameters, preconditions and runtime heartbeat status flow, unified encapsulation of VLA grasping, whole body movement control and active navigation, shielding the underlying differences of heterogeneous embodiment controllers.</li>\n<li><strong>Hierarchical multi-modal Scene graph (HMSG)</strong>: Constructs a four-layer topology structure consisting of floor, room, view and object, cleverly introduces the “view layer” to act as a bridge between geometric coordinates and appearance reasoning, supporting efficient spatial retrieval that mixes speed and slowness.</li>\n<li><strong>Open Vocabulary 3D Dynamic Semantic Mapping</strong>: Fusion of multi-camera neural depth estimation and multi-scale SigLIP features, combined with 3D instance back-projection correlation algorithm, to achieve local lightweight incremental refresh when physical changes occur in the environment.</li>\n<li><strong>real robot heterogeneous full-stack deployment verification</strong>: Completed deployment on Unitree G1 humanoid, R1 humanoid and dual-arm mobile chassis, comprehensively refreshing industry indicators on ScanNet semantic mapping and HM3D/real robot long-horizon navigation benchmarks.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题\">1. Background and problem</h3>\n<p>Large language model agents in the digital world rely on structured codes or software interfaces, with deterministic input and output, transparent state transitions, and reversible trial and error costs; however, in the physical world, the robot’s action execution is continuous, irreversible, and highly dependent on the specific body configuration. Due to perceptual degradation, sensor noise, and dynamic changes, robots often go to the wrong room due to outdated environmental memory, or long-horizon tasks are interrupted and crash due to incomplete feedback from the controller. This system-level obstacle is called the “Embodiment Gap.” Current embodied intelligence research often separates VLA operation strategies, 3D spatial representation, whole-body motion control, and active navigation into single-point algorithm modules. There is a lack of a unified operating system runtime to schedule heterogeneous skills, maintain a persistent 3D space base, and drive fault recovery based on real-time heartbeat evidence.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点\">2. Methods and innovations</h3>\n<h4 id=\"-整体框架概述\">① Overview of the overall framework</h4>\n<p>HoloAgent-0 organizes long-term embodied tasks into a self-Closed-loop systems project. The overall architecture includes three core coupling layers and a monitoring and verification layer, and implements strongly typed communication through the ROS2 topic bus:</p>\n<ul>\n<li><strong>Embodied AgentOS runtime layer</strong>: receives human natural language intentions, combines spatiotemporal memory to compile instructions into a skill graph with dependencies (Skill Graph), and is responsible for resource scheduling, execution status monitoring and autonomous re-planning during the execution period.</li>\n<li><strong>Embodied Skill Layer</strong>: Abstracts the underlying heterogeneous algorithms and controllers into typed skills (Typed Skills) with a unified interface, covering voice interaction, open vocabulary perception, autonomous navigation (HoloNavi), double-arm operation (HoloBrain) and whole-body movement (HoloMotion).</li>\n<li><strong>Embodied Memory Layer</strong>: Maintains three-dimensional metric geometry, topological navigation relationships, open vocabulary 3D semantic voxel maps, and hierarchical multimodal Scene graphs (HMSG) composed of floors, rooms, perspectives, and objects, while recording the temporal trajectory of task progress.</li>\n<li><strong>Monitoring &amp; Verification Layer (Monitoring &amp; Verification Layer)</strong>: Real-time monitoring of the heartbeat, confidence and error modes of skill execution, providing multi-modal interactive feedback to users, and waking up AgentOS for dynamic re-planning when unrecoverable faults occur.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-framework-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: HoloAgent-0 closed-loop end-to-end runtime architecture overview</a>\n<figcaption>HoloAgent-0 closed-loop End-to-end runtime architecture overview</figcaption>\n</div>\n<h4 id=\"-具身技能层与类型化动作抽象typed-skills\">② Embodied skill layer and Typed actions abstraction (Typed Skills)</h4>\n<p>In traditional large model tool calls, agents usually treat the underlying tools as black-box functions, but this can easily lead to deadlocks on physical robots. To this end, HoloAgent-0 proposes a structured skill abstract contract:</p>\n<ol>\n<li><strong>Command Schema</strong>: Each skill explicitly declares the name, strongly typed input parameters, preconditions (Preconditions) and expected physical post-state (Expected Effects). For example, operational skill <code class=\"language-plaintext highlighter-rouge\">pick(object=mug, support=table)</code> declares pre-geometric anchoring requirements for grasping objects and support planes.</li>\n<li><strong>Runtime Status Interface</strong>: The execution end no longer just returns a binary completion identifier, but continuously broadcasts structured tracking data including progress ratio, success status, fine-grained failure modes (such as object inaccessibility, grip slippage, collision risk, and posture singularity), algorithm confidence, execution delay, and whether the failure is recoverable (Recoverability) through the ROS2 status topic.</li>\n</ol>\n<h5 id=\"卡点降维-1数字软件工具调用-vs-具身类型化技能typed-skills\">Stuck Point Dimensionality Reduction 1: Digital Software Tool Calling vs. Embodied Typed Skills (Typed Skills)</h5>\n<table>\n<thead>\n<tr>\n<th>Compare dimensions</th>\n<th>Traditional digital agent tool calling (Software Tool Calling)</th>\n<th>HoloAgent-0 Embodied Typed Skill</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>calling property</strong></td>\n<td>Synchronous or short-term asynchronous API, with determined input and output and clear semantic boundaries</td>\n<td>The physical world is a continuous and time-consuming process that is susceptible to interference from dynamic noise, occlusion and sensor drift.</td>\n</tr>\n<tr>\n<td><strong>feedback granularity</strong></td>\n<td>Only the final execution result or standard error code is returned</td>\n<td>Continuously publish runtime heartbeat stream (including progress percentage, local confidence and collision risk)</td>\n</tr>\n<tr>\n<td><strong>failure mode</strong></td>\n<td>Single error code (such as HTTP 404/500), usually no physical side effects</td>\n<td>Subdivide recoverable and non-recoverable modes (such as robot arm joint limit, grip slip, target loss)</td>\n</tr>\n<tr>\n<td><strong>recovery mechanism</strong></td>\n<td>Simple fixed number of exception retries (Retry) or text error return</td>\n<td>Explicitly expose recoverability, driving AgentOS rotation perspective recheck, navigation fine-tuning or re-planning</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Specific execution flow example</strong>:\nThe robot received the instruction “Put the yellow towel on the table into the laundry basket.”</p>\n<ol>\n<li>AgentOS issues instructions <code class=\"language-plaintext highlighter-rouge\">pick(object=\"yellow towel\", support=\"desk\")</code> through the ROS2 topic;</li>\n<li>The HoloBrain operation backend takes over control and continues to return the status stream <code class=\"language-plaintext highlighter-rouge\">{progress: 40%, status: \"in_progress\", confidence: 0.88}</code> when the robotic arm moves to the pre-grasping pose;</li>\n<li>When the gripper is closed, the tactile and posture feedback detects an empty grip, and the status flow is immediately reported <code class=\"language-plaintext highlighter-rouge\">{progress: 75%, status: \"failed\", failure_mode: \"grasp_slip\", recoverability: \"recoverable\"}</code>;</li>\n<li>AgentOS captures that recoverability is true and does not mechanically repeat blind grasping. Instead, it automatically schedules the perception backend to perform viewpoint fine-tuning and mask re-evaluation, updates the 3D bounding box of the target object, and then reinitiates grasping closed-loop.</li>\n</ol>\n</blockquote>\n<p>For different body postures, HoloAgent-0 is connected to four specialized backends:</p>\n<ul>\n<li><strong>HoloNavi space navigation</strong>: responsible for target search and path cruising in a wide range of environments;</li>\n<li><strong>HoloBrain embodied operation</strong>: Based on the general VLA large model, it generates the end posture trajectory of both arms and end clamps, and can autonomously complete delicate operations such as grasping, placing, pouring water, and folding clothes;</li>\n<li><strong>HoloMotion full body motion</strong>: supports trajectory tracking mode (for human-computer interaction actions such as waving, bowing, shaking hands, dancing, etc.) and speed control mode (for omnidirectional walking, steering, emergency obstacle avoidance and recovery after falling);</li>\n<li><strong>Cross-Embodiment Coordination</strong>: Multiple heterogeneous robots divide labor through a shared 3D Spatial memory base and a unified step state flow. For example, a wheeled mobile chassis first inspects and builds maps and marks the target location, and the humanoid robot then accurately performs complex desktop operations.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-closed-loop-execution.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: A real closed-loop implementation case of HoloAgent-0 on a diversified robot platform (operation control, object finding, multi-machine collaboration, long-distance folding)</a>\n<figcaption>HoloAgent-0 A real closed-loop implementation case on a diversified robot platform (operation control, object finding, multi-machine collaboration, long-distance folding)</figcaption>\n</div>\n<h4 id=\"-空间记忆与开放词表-3d-语义建图\">③ Spatial memory and open vocabulary 3D semantic mapping</h4>\n<p>Spatial memory provides a unified metric three-dimensional physical base for robot perception and action:</p>\n<ul>\n<li><strong>Unified geometry base</strong>: Decoupled sensor hardware configuration, supporting not only metric mapping (such as FAST-LIVO) where lidar, IMU and cameras are tightly coupled, but also pure visual multi-camera GeoFlow-SLAM++ system. GeoFlow-SLAM++ uses a 3D basic model to directly predict dense depth from multi-view RGB images, and builds high-quality metric maps without a hardware depth camera through multi-camera two-stage optical flow matching, point and surface geometry optimization, and loop bag-of-word retrieval.</li>\n<li><strong>Open vocabulary semantic projection</strong>: The online mapping module seamlessly upgrades the universal semantics of the 2D basic model to the 3D point cloud and voxel grid.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-semantic-mapping.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: HoloAgent-0 open vocabulary 3D semantic mapping and dynamic scene adaptation framework</a>\n<figcaption>HoloAgent-0 Open Vocabulary 3D Semantic Mapping and Dynamic Scene Adaptation Framework</figcaption>\n</div>\n<h5 id=\"卡点降维-2三尺度-siglip-语义特征融合与-3d-实例持续关联\">Stuck Point Dimensionality Reduction 2: Three-Scale SigLIP Semantic Feature Fusion and 3D Instance Continuous Association</h5>\n<p>When upgrading 2D features to 3D space, if only a single cropped area feature is extracted, the environmental context is easily lost; if full image features are extracted, the discrimination of small objects will be diluted. HoloAgent-0 designed a multi-scale feature weighted fusion formula for this purpose:</p>\n\n\\[d = \\sum_{i=0}^2 w_i \\odot d_i\\]\n\n<p>Here, $d_i \\in \\mathbb R^d$ and $w_i \\in \\mathbb R^d$ are feature fusion weights, and $\\odot$ represents the Hadamard product.</p>\n<blockquote>\n<p><strong>A small example of hand-calculated feature fusion and projection correlation</strong>:\nAssume that the feature dimension is simplified to 3 dimensions, and a water glass is detected in the current key frame:</p>\n<ol>\n<li>Extract SigLIP embedding vectors at three scales:\n      <ul>\n<li>Full image context feature $d_0 = [0.2, 0.8, 0.1]$ (records large scene information such as kitchen and workbench);</li>\n<li>SAM2 precise segmentation mask feature $d_1 = [0.9, 0.1, 0.3]$ (highlighting the material and shape of the water cup);</li>\n<li>Minimum external rectangular frame feature $d_2 = [0.7, 0.4, 0.2]$ (supplementary handle and tabletop contact edge details);</li>\n</ul>\n</li>\n<li>Assume that the corresponding feature balance weight vectors are $w_0 = [0.2, 0.2, 0.2]$, $w_1 = [0.5, 0.5, 0.5]$, and $w_2 = [0.3, 0.3, 0.3]$;</li>\n<li>The final object vector after element-by-element fusion is:\n$d = (0.2 \\times [0.2, 0.8, 0.1]) + (0.5 \\times [0.9, 0.1, 0.3]) + (0.3 \\times [0.7, 0.4, 0.2]) = [0.70, 0.33, 0.23]$. This vector combines macroscopic scene attribution with local appearance details.</li>\n<li><strong>cross-view 3D instance association</strong>: When a new frame is collected after the robot is displaced, the system back-projects the maintained 3D instance point cloud $V_{t-1}$ back to the current camera plane through the external parameter matrix to obtain the projection prediction mask $\\tilde m_j$. The system calculates the intersection ratio $\\operatorname{IoU}(m_k, \\tilde m_j)$ of $\\tilde m_j$ and the current new segmentation mask $m_k$. If the intersection ratio is greater than 0.5, it is considered to be the same object and the unique instance ID is reused; if there is no overlap, a new 3D independent instance is opened.</li>\n</ol>\n</blockquote>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-instance-association.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Cross-time frame 3D instance back-projection matching and continuous ID tracking mechanism</a>\n<figcaption> Cross-time frame 3D instance back-projection matching and continuous ID tracking mechanism</figcaption>\n</div>\n<h4 id=\"-分层多模态场景图hmsg与快慢混合检索机制\">④ Hierarchical multi-modal Scene graph (HMSG) and fast and slow hybrid retrieval mechanism</h4>\n<p>In order to take into account both spatial range and fine-grained perception, HMSG vertically decouples environmental information into a four-layer topology:</p>\n<ol>\n<li><strong>Floor</strong>: records the vertical height range and the overall semantics of the floor, and delineates the vertical range in coarse granularity;</li>\n<li><strong>Room layer (Room)</strong>: Contains 2D polygon geometric boundaries, point clouds and room type CLIP vectors to define the functional space;</li>\n<li><strong>perspective layer (View)</strong>: <strong>, the core innovation layer of</strong>HMSG. Record the 6-DoF rigid body pose, RGB-D image frame and local panoramic descriptor at the historical sampling location of the robot;</li>\n<li><strong>Object layer (Object)</strong>: Maintain 3D Oriented BBox, point cloud clusters and fused instance SigLIP features.</li>\n</ol>\n<pre><code class=\"language-mermaid\">graph TD\n    subgraph S1[\"1. Language intent decomposition\"]\n        A[\"Enter natural language commands&lt;br/&gt;'found1Pills on bedside table in upstairs bedroom'\"] --&gt; B[\"LLM Hierarchical semantic parsing&lt;br/&gt;Extract: Floor/room/target object\"]\n    end\n\n    subgraph S2[\"2. HMSG Quick initial screening (Fast Matching)\"]\n        B --&gt; C[\"Floor match: Filter to Floor-1\"]\n        C --&gt; D[\"Room match: Lock Bedroom\"]\n        D --&gt; E[\"CLIP Characteristic coarse screening&lt;br/&gt;primaries Top-K candidate perspective View\"]\n    end\n\n    subgraph S3[\"3. Multimodal slow verification (Slow Reasoning)\"]\n        E --&gt; F[\"VLM Review candidate perspective images&lt;br/&gt;'Whether there are tablets in the current field of view?'\"]\n        F -- \"confirm existence\" --&gt; G[\"Compute objects 3D Space center coordinates&lt;br/&gt;Dispatch navigation to the best operating position\"]\n        F -- \"not detected / Obstructed viewing angle\" --&gt; H[\"Rotate the body in place to capture a partial panorama&lt;br/&gt;Perform secondary word opening detection and retry\"]\n    end\n\n    subgraph S4[\"4. Active exploration of frontiers (Frontier Exploration)\"]\n        H -- \"Second verification still fails\" --&gt; I[\"Determine memory failure or no mapping&lt;br/&gt;Compute unexplored boundaries Frontier\"]\n        I --&gt; J[\"Comprehensive information gain and popularity navigation exploration&lt;br/&gt;Dynamic updates while walking HMSG Scene graph\"]\n    end\n</code></pre>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-hmsg-structure.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Hierarchical multimodal Scene graph (HMSG) four-layer structure (floor-room-view-object) and hierarchy and topological edge association</a>\n<figcaption> Hierarchical multimodal Scene graph (HMSG) four-layer structure (floor-room-view-object) and level and topological edge association</figcaption>\n</div>\n<p>The traditional Scene graph points directly across the room to discrete objects, resulting in the robot’s lack of perception of the real observation angle and occlusion conditions. Blindly calling the time-consuming multi-modal model (VLM) when facing a large space will cause a computing power collapse. The “View” in HMSG naturally retains the visual links (Visibility Links) between the observer’s perspective and objects, allowing the system to quickly screen out a very small number of relevant perspectives on metric geometry, and then call VLM specifically for high-quality visual identification.</p>\n<h4 id=\"-holonavi-目标导航流水线\">⑤ HoloNavi target navigation pipeline</h4>\n<p>Based on HMSG, the HoloNavi navigation system connects tasks into three interlocking execution loops:</p>\n<ol>\n<li><strong>Hierarchical Object Navigation</strong>: Use semantic analysis to match floor, room and object candidates, and use hierarchical CLIP similarity to quickly prune the irrelevant search space;</li>\n<li><strong>Online Verification Loop</strong>: When the robot reaches the candidate viewpoint, the real-time camera image is submitted to the open word detector and VLM for double verification. If the initial determination fails, the robot automatically rotates in place at multiple angles to collect the surrounding perspective for a second recheck, confirms the true coordinates of the target and then navigates to a safe operating distance;</li>\n<li><strong>Frontier Exploration Loop</strong>: If the initial search of HMSG fails or the online verification fails again, the system immediately switches to Frontier Exploration mode. Comprehensive scoring is performed based on the information gain expectation, task semantic relevance, traversability and dynamic constraints of the candidate frontier points, guiding the robot to explore unknown areas and continue to perform incremental mapping and target sniffing while traveling.</li>\n</ol>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-holonavi-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The whole process of HoloNavi object navigation: hierarchical semantic matching, online multi-view verification and cutting-edge incremental exploration</a>\n<figcaption> HoloNavi object target navigation whole process: hierarchical semantic matching, online multi-view verification and cutting-edge incremental exploration</figcaption>\n</div>\n<h4 id=\"-动态时空记忆自适应增量更新dynamic-memory-update\">⑥ Dynamic spatiotemporal memory adaptive incremental update (Dynamic Memory Update)</h4>\n<p>The real world is constantly evolving. HoloAgent-0 defines three types of core events that trigger memory refresh:</p>\n<ul>\n<li><strong>Perception conflict event</strong>: The new sensor data and the existing map are significantly offset in spatial geometry or color;</li>\n<li><strong>skill operation result event</strong>: The robot performs grasping placement (such as picking up a water cup) to cause the object to break away from the original support surface, or navigation is blocked and new obstacles are exposed;</li>\n<li><strong>Human explicit feedback event</strong>: The user issued error correction instructions for room naming or object attributes through voice.</li>\n</ul>\n<p>When performing an update, the memory layer first uses the current observation to perform robust relocation in the existing geometric map, locally clears out-of-date point clouds and voxels that cause conflicts, and integrates new features into the local geometry. The semantic layer updates the bounding box of the affected 3D instance, and HMSG <strong>only performs an in-situ topology update</strong> on the affected local subgraph (recalculates the room and visual angle to which the object belongs), without having to bear the high cost of reconstructing the entire global Scene graph.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-dynamic-memory-update.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of adaptive refresh of local scene memory in dynamic environment (in-situ update of local map and Scene graph subgraph after desktop objects move)</a>\n<figcaption> Comparison of adaptive refresh of local scene memory in dynamic environment (in-situ update of local map and Scene graph subgraph after desktop object moves)</figcaption>\n</div>\n<hr/>\n<h3 id=\"3-核心结果发现\">3. Results and findings</h3>\n<ul>\n<li><strong>HM3D-ObjNav simulation benchmark navigation performance jumps</strong>: Under the standard simulation benchmark without hardware noise, HoloAgent-Nav equipped with AgentOS closed-loop achieved a success rate (SR) of <strong>82.6%</strong> and <strong>42.8% path length weighted success rate (SPL)</strong> is significantly ahead of existing representative navigation solutions in the industry, such as MSGNav (74.1% SR / 33.4% SPL), WMNav (72.2% SR / 33.3% SPL) and FSR-VLN in open-loop state (80.8% SR / 41.0% SPL), confirming that the closed-loop monitoring and retry re-planning mechanism can significantly improve the completion rate of complex tasks while ensuring path efficiency.</li>\n<li><strong>Excellent robustness of long-distance navigation in real physical apartments</strong>: In the multi-target search evaluation of real indoor apartments, HoloAgent-Nav achieved a real arrival rate of <strong>97.70%</strong> under the most stringent Top-1@1.0m hit standard, and the Top-5 arrival rate reached <strong>98.90%</strong>; for comparison, the well-known baseline OK-Robot in the same scenario has only 60.92%, HOV-SG only 51.72%, and MobilityVLA only 34.48%. What’s even more striking is that the scores of HoloAgent-Nav under different judgment thresholds of 1.0m, 2.0m and 3.0m are completely consistent, indicating that the successful samples all accurately approach the core operating area within 1.0m, showing extremely robust position and orientation docking accuracy.</li>\n<li><strong>High-quality open vocabulary 3D semantic mapping</strong>: On the ScanNet data set, HoloAgent-Memory achieved <strong>31.58% mIoU</strong> and <strong>61.58% in online (Online) computing mode Frequency-weighted accuracy (f-Acc)</strong>, the performance clearly overwhelms other online mapping algorithms (such as Open-Fusion’s 18.02% mIoU, Concept-Graph’s 16.29% mIoU), and even approaches the large model mapping algorithm of offline computing, providing a solid and accurate high-quality semantic index base for upper-layer agents.</li>\n<li><strong>real robot multi-morphological complex long-distance composite tasks</strong>: Successfully completed on the Unitree G1/R1 bipedal humanoid and two-arm mobile platform including “finding objects from the bedroom”, “multi-machine voice collaborative dance guidance” and the extremely challenging “long-distance mobile laundry folding” (covering autonomous cruising from the mobile chassis to the target workstation, flexible clothing sorting and grasping with both arms) , table tiles to fine folding) and many other closed-loop tasks.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性\">4. Limitations</h3>\n<ul>\n<li>At present, the basic model of robot embodiment is still unable to seamlessly cover the complete action spectrum from large-scale spatial navigation, precise dual-arm operation to whole-body torque-level motion control with a single model. The system’s cross-embodiment migration of different physical configurations still relies on engineered controller bridging and dynamics tuning.</li>\n<li>The industry still lacks an end-to-end unified long-horizon real robot evaluation benchmark covering operation, multi-modal navigation and whole-body dynamic interaction. For large-scale complex architectural scenes, there is still room for further improvement in the delay of long-term cross-view feature fusion and fine-grained geometric reconstruction accuracy.</li>\n</ul>\n<h2 id=\"pigey\">2. Pigey (2026)</h2>\n<p>———Addressing the Orchestration Gap in Generalist Robots via Physical Agency</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2607.21725\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2607.21725</a></p>\n<hr/>\n<h3 id=\"精华-1\">Key takeaways</h3>\n<ul>\n<li><strong>reveals the “Orchestration Gap” of embodied intelligence</strong>: It is pointed out that the main bottleneck of current general-purpose robots is not the lack of low-level motion control capabilities, but the lack of a closed-loop orchestration architecture that can coordinate perception, planning, verification and recovery; a single end-to-end model is easily overfitted and blindly executed when directly prompted, resulting in greatly limited performance.</li>\n<li><strong>Pure inference time closed-loop physical agent (no need for any new training)</strong>: Build a closed-loop orchestrator Pigey driven by the Frontier Visual Language Model (Frontier VLM), decompose complex long-term instructions into short-term sub-goals, and only call the frozen motion strategy of the underlying organization through high-level perception and tools, without retraining or fine-tuning low-level weights at all.</li>\n<li><strong>Geometric Programming (TAMP) and Neural Strategy ($\\pi_{0.5}$) Complementary Dual Backend</strong>: Combining deterministic tasks with motion planning (TiP ToP) and end-to-end visual motion strategy ($\\pi_{0.5}$) are decoupled and integrated - rigid objects use grab-and-place planning with geometric certainty, and deformable objects, contact-intensive operations, or planning are seamlessly upgraded to VLA.</li>\n<li><strong>sensor and wrist vision conservative double verification mechanism</strong>: Split the open-loop “grab-and-release” atomic action, and use the gripper width sensor (<code class=\"language-plaintext highlighter-rouge\">is_grasped</code>) combined with the wrist camera image to perform strict conservative verification after grasping; if grasping is not stable, immediately retry or upgrade in place, eliminating the compound error of “empty gripper delivery” from the source.</li>\n<li><strong>out-of-distribution and real robot long-term task performance leap</strong>: The frozen $\\pi_{0.5}$-LIBERO zero-sample success rate soared from 12.8% to 53.3% on the strong perturbation benchmark LIBERO-PRO; it reached 97.3% in 30 complex long-term evaluations of the real DROID robotic arm The overall success rate (baseline $\\pi_{0.5}$ is only 16.7%).</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-1\">1. Background and problem</h3>\n<p>With the development of large models and robotics technology, the field of robotics generally tends to build huge single vision-language-action (VLA) models, hoping to integrate high-level semantic understanding, common sense reasoning, space planning, successful detection, abnormality recovery and underlying millimeter-level motor control into the same neural network through large-scale pre-training. However, this monolithic end-to-end paradigm faces practical bottlenecks that are difficult to overcome:</p>\n<ol>\n<li><strong>Instruction sensitivity and semantic degradation</strong>: In the end-to-end strategy, high-level natural language instructions often degrade into weak prior conditions, and the model can easily fall into the mechanical memory of specific training trajectories and completely lose its ability to adjust when faced with scene disturbances (such as target displacement, occlusions, and the target is occupied);</li>\n<li><strong>open-loop execution and compound errors</strong>: Existing code-as-policies or traditional task and motion planning (TAMP) often rely on one-time offline generation and are in an open-loop blind running state during the execution phase; once grasping slippage or collision occurs in the middle, the system still advances mechanically according to the predetermined trajectory, and ultimately fails completely;</li>\n<li><strong>Lack of orchestration capabilities</strong>: True physical versatility requires the system to have a “Physical Agency” - not only knowing “what to do”, but also observing “whether it was done or not” during execution, and actively retrying, bypassing obstacles or changing means when it fails.</li>\n</ol>\n<p><strong>Core question</strong>: Without retraining or fine-tuning the underlying motion strategy at all, can the full potential of the pre-trained frozen strategy be unleashed and bridge the “orchestration gap” of general-purpose robots through only a closed-loop physical orchestration framework at inference time?</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-1\">2. Methods and innovations</h3>\n<p>The core idea of Pigey is to decouple <strong>control and orchestration</strong>: the bottom layer only retains two frozen motion executors (TAMP planner and $\\pi_{0.5}$ VLA), and the upper layer consists of cutting-edge VLM (such as multi-modal cutting-edge large models such as Claude/GPT) to form a closed-loop decision-making brain, running “Perceive”→ The physical execution cycle of “Reason → Action → Verify”.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Pigey closed-loop physical Agent system architecture: cutting-edge VLM acts as an orchestrator to coordinate perception, reasoning, execution and double verification, routing down to the frozen TAMP and VLA motion backends</a>\n<figcaption>Pigey closed-loop physical Agent system architecture: Frontier VLM acts as an orchestrator to coordinate perception, reasoning, execution and double verification, routing down to the frozen TAMP and VLA motion backend</figcaption>\n</div>\n<h4 id=\"-整体框架概述-1\">① Overview of the overall framework</h4>\n<p>As a closed-loop embodied intelligence Agent, Pigey maintains the global context history $h$ after receiving the global long instruction $I$ (for example: “A child is visiting - put the toys on the plate and put the dangerous items in the box”). In each step of interaction, VLM only selects and calls a structured tool (Tool Call), obtains real feedback from the physical world sensors and cameras, and updates the internal state accordingly until all sub-goals are achieved and terminated by calling <code class=\"language-plaintext highlighter-rouge\">Done</code>.</p>\n<p>The system splits the complex responsibilities originally undertaken by a single large model into clear module chains:</p>\n<ul>\n<li><strong>Open vocabulary target perception and spatial anchoring</strong>: Use the open vocabulary detector to lock objects and their labels in the scene to limit the vocabulary space of high-level planning;</li>\n<li><strong>Task-level long-term memory</strong>: Maintain the list of completed operations, current gripper holdings and remaining items on the desktop;</li>\n<li><strong>Geometry and Neural Dual Motion Backend</strong>: Rigid catch-and-release analytically verifiable TAMP, irregular/contact-intensive operation VLA;</li>\n<li><strong>Conservative double verification and two-way upgrading and downgrading engine</strong>: Sensor signals and visual judgments support each other, driving retry, troubleshooting and strategy switching.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Pigey’s physical reasoning capabilities demonstrated in real robot dog/robot arm scenarios: deductive reasoning, safety common sense, obstacle elimination, long-term scene memory and spatial geometry stacking</a>\n<figcaption>Pigey’s physical reasoning capabilities demonstrated in real robot dog/robot arm scenarios: deductive reasoning, safety common sense, obstacle elimination, long-term scene memory and spatial geometry stacking</figcaption>\n</div>\n<h4 id=\"-逐模块讲解\">② Explain module by module</h4>\n<ul>\n<li><strong>Perception and target semantic anchoring (Perceive &amp; Grounding)</strong>\n<ul>\n<li><strong>Input</strong>: multi-view camera images (main view and wrist view) and underlying robot joint status.</li>\n<li><strong>Processing</strong>: Call the open vocabulary detector to generate a set of object candidates with bounding boxes and semantic labels. These detection tags strictly constitute Pigey’s “controlled vocabulary” (Vocabulary), and the parameters of all grasping or placement operations must directly reference the detection tags.</li>\n<li><strong>output</strong>: structured scene perception dictionary, including object label list, local high-resolution image of the wrist and current gripper status.</li>\n<li><strong>Design motivation</strong>: To prevent the language model from inventing the names of unseen objects out of thin air in physical interactions, connect high-level fuzzy concepts (such as “dangerous goods”, “vegetarian food”, “smallest container”) directly to specific entities that have been positioned in the physical scene.</li>\n</ul>\n</li>\n<li><strong>Decoupled complementary dual-motion backends (Frozen Motor Backends)</strong>\n<ul>\n<li><strong>TAMP geometric backend (<code class=\"language-plaintext highlighter-rouge\">Pick(ℓ)</code> / <code class=\"language-plaintext highlighter-rouge\">DropAbove(ℓ)</code>)</strong>: built based on the TiPToP framework, responsible for spatial collision-free motion planning and six-degree-of-freedom geometric grasping pose generation. Pigey performed a key refactoring - forcibly cutting Pick-and-Place, which was originally packaged as a single open-loop execution, into two independent tool calls, and inserting physical verification between grasping and placement.</li>\n<li><strong>VLA neural backend (<code class=\"language-plaintext highlighter-rouge\">VLARollout(s)</code>)</strong>: encapsulates frozen pre-training $\\pi_{0.5}$ closed-loop visual action control model, receiving short plain text sub-action description $s$ (such as <code class=\"language-plaintext highlighter-rouge\">“grasp the cable”</code>), directly outputs continuous high-frequency end displacement and clamping jaw opening and closing.</li>\n<li><strong>collaborative mechanism</strong>: Conventional rigid objects tiled on the desktop call TAMP first to obtain extremely high trajectory certainty; stacked objects, easily deformable objects (such as cables, plush toys), or objects in deep containers are directly solved by VLA with compliant control characteristics.</li>\n</ul>\n</li>\n<li><strong>Conservative Dual Verification</strong>\n<ul>\n<li><strong>input</strong>: the Boolean quantity <code class=\"language-plaintext highlighter-rouge\">is_grasped</code> read by the displacement sensor embedded in the gripper, and the hand-eye (wrist) camera snapshot after the action is completed.</li>\n<li><strong>processing</strong>: The hardware sensor is used to confirm whether the physical clamping gap is within the clamping threshold; the leading edge VLM simultaneously observes the wrist camera to determine whether the target object in the field of view has been moved away from its original position and is in the center of the clamping jaw.</li>\n<li><strong>conservative synthesis rule</strong>: Both adopt the most pessimistic strategy - even if the motion backend report is completed, as long as <code class=\"language-plaintext highlighter-rouge\">is_grasped == False</code> or the visual display target is still on the table, the step will be immediately judged as a failure and subsequent actions will be cancelled.</li>\n</ul>\n</li>\n</ul>\n<h4 id=\"-卡点降维与决策流图\">③ Dimensionality reduction and decision flow diagram of stuck points</h4>\n<p>Readers in the field of embodied intelligence are often confused: <strong>Why is the single end-to-end model (such as $\\pi_0$ / $\\pi_{0.5}$) still unable to perform simple catch and release with perturbation after large-scale pre-training? What exactly did Pigey’s closed-loop orchestration change?</strong></p>\n<p>We dismantle its inner mechanism through the self-made Mermaid decision flow chart and comparison table:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    Start[\"input: Natural language long instructions I + Scene global observation\"] --&gt; Perceive[\"Perceive: Open vocabulary detection object label collection\"]\n    Perceive --&gt; Reason[\"Reason: Plan the next short-term sub-goal based on situational history\"]\n    Reason --&gt; CheckType{\"Target object type and physical state?\"}\n    CheckType -- \"desktop rigid object\" --&gt; CallTAMP[\"call TAMP Planner: Pick(ℓ)\"]\n    CheckType -- \"Flexible/Cable/complex contact\" --&gt; CallVLA[\"call π0.5 VLA: VLARollout(s)\"]\n    CallTAMP --&gt; DualVerify{\"double check: is_grasped and the wrist image is in place?\"}\n    CallVLA --&gt; DualVerify\n    DualVerify -- \"Verification passed (True)\" --&gt; Place[\"Allow to proceed to next step: DropAbove(Target location)\"]\n    DualVerify -- \"Verification failed (False)\" --&gt; CheckRetry{\"Number of retries?\"}\n    CheckRetry -- \"first failure\" --&gt; Retry[\"Re-perceive and update pose -&gt; Try again in place\"]\n    CheckRetry -- \"Second failure\" --&gt; Escalate[\"Two-way strategy upgrade: TAMP switch to VLA\"]\n    Retry --&gt; CallTAMP\n    Escalate --&gt; CallVLA\n    Place --&gt; CheckAllDone{\"Has the global goal been achieved??\"}\n    CheckAllDone -- \"Not completed\" --&gt; Reason\n    CheckAllDone -- \"All done\" --&gt; Finish[\"call Done terminate and deliver\"]\n</code></pre>\n<p>To further see Pigey’s subversion of the traditional robot control paradigm, the comparison table is as follows:</p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>End-to-end single VLA (such as $\\pi_{0.5}$ / OpenVLA)</th>\n<th>open-loop code planning (Code-as-Policies / TiPToP)</th>\n<th>closed-loop physical agent (Pigey article)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Control division of labor</strong></td>\n<td>Language understanding, planning, verification and motion control are all coupled into a single large model</td>\n<td>LLM generates complete Python code or action plan, and the underlying open-loop is completed</td>\n<td>Frontier VLM is only responsible for closed-loop orchestration and verification, and all actions are delegated to the freezing strategy</td>\n</tr>\n<tr>\n<td><strong>execution mode</strong></td>\n<td>Step autoregressive, lack of reflection on macro task status</td>\n<td>One-time planning, “blind” to object slippage and environmental changes during execution</td>\n<td>Each tool call must undergo double verification by sensors and vision, and dynamic closed-loop advancement</td>\n</tr>\n<tr>\n<td><strong>Abnormal recovery</strong></td>\n<td>Extremely poor (after catching the air, continue to place the air gripper later)</td>\n<td>None (planning failure or execution interruption directly throws an exception and crashes)</td>\n<td>Native support for obstacle removal, replacement and re-grabbing, TAMP and VLA two-way upgrading and downgrading</td>\n</tr>\n<tr>\n<td><strong>Training cost</strong></td>\n<td>Tens of thousands of hours of real robot trajectory re-fine-tuning/post-training are required</td>\n<td>No training required, but relies on an ideal simulation environment</td>\n<td><strong>Zero fine-tuning</strong>, fully utilizing ready-made frozen pre-trained models and classic planners</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>gives an example (target displacement and empty recovery)</strong>:\nSuppose the task is “put the red cup into the tray”.</p>\n<ul>\n<li><strong>single VLA / open-loop planning</strong>: calculate the grasping trajectory and execute placement directly and coherently. If the cup is bumped and slips when the robotic arm reaches down, the robotic arm will still close the empty gripper and move it to the top of the tray to release it, thinking that the “mission is completed”, and ultimately failing completely.</li>\n<li><strong>Pigey closed-loop processing</strong>:\n      <ol>\n<li>Execute <code class=\"language-plaintext highlighter-rouge\">Pick(red_cup)</code>;</li>\n<li>After the robotic arm is closed, the gripper width sensor returns to <code class=\"language-plaintext highlighter-rouge\">is_grasped = False</code>, and the wrist image detects that the cup is still in place;</li>\n<li>Pigey intercepts the subsequent <code class=\"language-plaintext highlighter-rouge\">DropAbove</code> action and records grasping failure;</li>\n<li>Trigger <code class=\"language-plaintext highlighter-rouge\">Perceive</code> to re-detect the precise coordinates of the cup after displacement, update the grasping posture and try again; if the cup is still not grasped correctly the second time, the backend is actively upgraded to <code class=\"language-plaintext highlighter-rouge\">VLARollout</code> with supple fault tolerance to implement tactile grasping, ultimately ensuring that the cup is securely placed on the plate.</li>\n</ol>\n</li>\n</ul>\n</blockquote>\n<hr/>\n<h3 id=\"3-核心结果发现-1\">3. Results and findings</h3>\n<p>The paper conducted a system comparative evaluation on the simulation benchmark LIBERO-PRO and the DROID workbench based on the real Franka robotic arm, which fully verified the multiplication effect of inference time physical orchestration on model capabilities.</p>\n<h4 id=\"-libero-pro-仿真基准评测\">① LIBERO-PRO simulation benchmark evaluation</h4>\n<p>LIBERO-PRO is the industry’s most difficult perturbation test benchmark for complex long-term desktop operations. It introduces six rigorous perturbation suites, including object position swap (Obj. swap), target attribute swap (Goal swap), and spatial geometry perturbation (Spatial swap/task).</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-libero-pro.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of success rates under LIBERO-PRO's six major perturbation suites: keeping the underlying frozen weights completely unchanged and only changing the inference orchestration mechanism</a>\n<figcaption>LIBERO-PRO Success rate comparison under six major perturbation suites: keeping the underlying frozen weight completely unchanged, only changing the inference orchestration mechanism</figcaption>\n</div>\n<ul>\n<li>The performance of the original SOTA VLA of <strong>has seriously declined.</strong>: When running directly with the open-loop prompt, even the current top $\\pi_{0.5}$-LIBERO has an average success rate of only <strong>12.8%</strong>, and directly returns to zero in multiple tasks, proving that the end-to-end strategy has seriously overfitted the training set trajectory.</li>\n<li><strong>Pigey achieves SOTA breakthrough</strong>: Under a zero-sample setting that does not use task-specific memory at all and does not fine-tune any weights, Pigey increases the average success rate of the freezing strategy to <strong>53.3%</strong>. Compared with the original strategy, it achieves a performance improvement of more than 4 times, significantly exceeding the code generation baseline. CaP-Agent0 (18.2%).</li>\n</ul>\n<h4 id=\"-真实机械臂droid能力测试\">② Real robot arm (DROID) capability test</h4>\n<p>In the real robot experiment, the research team set up 30 rigorous long-term tasks in 8 core competency dimensions, including common sense reasoning, conditional logic, spatial reasoning, obstacle clearance safety reasoning, active error recovery, and long-term memory recovery.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-droid-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Type 8 capability probe success rate (%) on the real robots arm DROID: The bottom layer all runs the same π0.5-DROID weight</a>\n<figcaption> Type 8 capability probe success rate (%) on the real robot arm DROID: The bottom layer all runs the same π0.5-DROID weight</figcaption>\n</div>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-qualitative-rollout.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Real robot long-term execution and single-frame inference chain demonstration: identifying non-vegetarian food and placing it in the bowl in sequence in the vegetarian selection task</a>\n<figcaption> real robot long-term execution and single-frame inference chain demonstration: identifying non-vegetarian food in the vegetarian selection task and placing it in the bowl in sequence</figcaption>\n</div>\n<ul>\n<li><strong>comprehensive success rate 97.3% vs 16.7%</strong>: $\\pi_{0.5}$-DROID under direct prompts was almost completely wiped out on tasks requiring common sense reasoning, multi-step logic and spatial geometry (success rates were all 0%), with an overall success rate of only 16.7%; while Pigey relied on closed-loop common sense orchestration With backtracking verification, it achieved 100% perfect scores in most categories, with a total success rate as high as <strong>97.3%</strong>.</li>\n<li><strong>real robot abnormal recovery record</strong>: When the placed target is occupied by foreign objects (such as debris in the coffee cup), Pigey can independently reason out the cascade recovery logic of “first remove the debris, place it next to it, and then put the target object in”; when the blind box blocks the target, it can infer that the target is under the box and actively lift the box to retrieve the object.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-1\">4. Limitations</h3>\n<ol>\n<li><strong>relies on cutting-edge large models for visual understanding and reasoning delay</strong>: Since the cloud or high-specification VLM needs to be called after each key action for visual reflection and decision-making, the overall task execution rhythm is limited by API communication and reasoning throughput, and the interaction delay is higher than that of a single end-to-end model;</li>\n<li><strong>The physical limit of the underlying action strategy cannot be exceeded</strong>: Although the orchestrator can greatly repair logic and grasping timing errors, if both underlying motion backends (TAMP solver and $\\pi_{0.5}$) cannot generate valid end trajectories due to singular points, collision deadlocks, or physical deformation distortion, it is still difficult for the upper-layer Agent to complete physical contact out of thin air.</li>\n</ol>\n<hr/>\n<h2 id=\"thea\">3. Thea (2026)</h2>\n<p>———Towards the Harness of Embodied Agents</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2608.11246\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2608.11246</a> · <a href=\"https://github.com/EIT-HAI/Thea\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a> · <a href=\"https://eit-hai.github.io/thea\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-2\">Key takeaways</h3>\n<ul>\n<li><strong>Migrating the “Code Agent Harness Paradigm” to the Embodied Physical World</strong>: Analogous to the successful essence of Claude Code and Codex in software engineering, it lies in the test feedback closed-loop (Harness) rather than the single model itself. It is pointed out that the key to realizing complex long-term tasks with embodied intelligence also lies in building a closed-loop Harness infrastructure that connects the physical reality.</li>\n<li><strong>Complements the two missing signal infrastructures in the physical world</strong>: The software world naturally has “reading world status” (file tree/AST) and “judging action results” (exit code/error call stack), while the physical world has neither. Thea innovatively proposed two cornerstone mechanisms, <strong>SceneGraph as Context</strong> (Scene graph is context) and <strong>Evaluation as Exit Codes</strong> (evaluator is exit code), to realize physical closed-loop.</li>\n<li><strong>Strict reliability theory establishes the theoretical bound of evaluation accuracy $\\alpha$</strong>: Mathematically proves that the success rate of long-term tasks open-loop exponentially decays with the number of steps $n$ ($P_{\\text{open}} = \\prod p_i \\to 0$); the error correction upper limit of closed-loop Harness strictly depends on the independent evaluator The judgment accuracy rate is $\\alpha$ (“The upper limit of Harness is determined by its judge”).</li>\n<li><strong>Cross-platform portability of decoupled models and embodiments</strong>: Defines the standardized embodiment Profile and Tool abstract contracts, the model (LLM/VLM) and the hardware embodiment (bipedal humanoid Unitree G1, bionic humanoid Astribot S1, double-arm wheeled AgileX Cobot Magic) are bidirectionally pluggable and replaceable, and a single set of architectures is deployed aCross-embodiments.</li>\n<li><strong>long-term compound task performance jumped significantly</strong>: In the real physics evaluation of multi-stage complex tasks (L1~L3), as the task complexity and number of steps increased, the success rate of traditional end-to-end strategies (ACT, $\\pi_{0.5}$, LingBot-VLA) dropped sharply to 30%~40%, while Thea still maintained the highest difficulty level at L3 Ultra-high success rate of <strong>87%</strong>.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-2\">1. Background and problem</h3>\n<p>The explosion of coding agents (Coding Agents, such as Claude Code, SWE-agent) has completely changed software engineering. The success of this type of system does not rest on the Superman model of “writing perfect code at once”, but on the <strong>test and retry closed-loop mechanism (Harness)</strong> composed of the compiler, testing framework and Git - the agent runs the test after writing the code, captures stack errors, reflects on modifications and iterates repeatedly until the test passes.</p>\n<p>When researchers attempted to translate this efficient Harness paradigm to the physical world, they encountered an essential structural gap. The foundational support that has taken decades to build up in the software world is all missing in the physical world:</p>\n<ol>\n<li><strong>state cannot be “read” natively</strong>: The code world has clear file systems and type symbols; while the sensors of physical robots only spit out chaotic and unstructured high-dimensional continuous point clouds and image pixels, which large models cannot directly use as accurate inferable context;</li>\n<li><strong>action cannot be “determined” natively</strong>: If an error occurs in the running program, a clear non-zero exit code (Exit Code) and stack trace (Stack Trace) will be returned immediately; but in reality, if the robotic arm reaches out to grasp, loses its hand, or collides, the physical world is silent. It will neither return a status code nor actively notify that “the action has ended”, resulting in infinite accumulation of errors during open-loop execution.</li>\n</ol>\n<p><strong>Core question</strong>: How to build a set of embodied Harness in the physical world that can provide “persistent readable state” and “accurate exit code determination”, so that high-level language/multi-modal models can reliably orchestrate underlying heterogeneous motion strategies and achieve closed-loop self-healing for long-term tasks?</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-2\">2. Methods and innovations</h3>\n<p>Thea built an embodied closed-loop Harness that decouples the cutting-edge decision-making model (Model) from the diverse robot embodiment (Body) orchestration, and closed the embodied control loop through structured context evolution, standardized tool interfaces, and independent post-evaluators.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Thea Embodied Harness System Panorama: Completely decouple model (Model) and embodiment (Body), establish a perception-action-verification closed-loop through callable tools (Tool), Scene graph context (Scene graph) and independent evaluator (Evaluator), and verify it on three different embodiments</a>\n<figcaption>Thea Embodied Harness system panorama: Completely decouple the model (Model) and embodiment (Body), establish a perception-action-verification closed-loop through callable tools (Tool), Scene graph context (Scene graph) and independent evaluator (Evaluator), and verify it on three different embodiments</figcaption>\n</div>\n<h4 id=\"-整体框架概述-2\">① Overview of the overall framework</h4>\n<p>In the Thea architecture, embodied agent consists of four core components:</p>\n<ol>\n<li><strong>model (Model)</strong>: high-level large language/visual language model, only responsible for understanding tasks, reading dynamic context, and output structured tool calls;</li>\n<li><strong>embodiment and tool layer (Body &amp; Tools)</strong>: Unify the underlying mobile navigation, robotic arm grasping, and skill strategies (such as ACT, diffusion strategy, $\\pi_0$) into a standardized Tool with pre-check (Pre-hook) and post-trigger (Post-hook);</li>\n<li><strong>Scene graph context (SceneGraph as Context)</strong>: Precipitate a persistent, symbolic Scene graph with 3D bounding boxes and topological relationships from the continuous perceptual flow, analogous to the file system in software engineering;</li>\n<li><strong>exit code evaluator (Evaluation as Exit Codes)</strong>: an independent visual evaluator triggered by the system structure after each action, returning a three-state execution verdict (Success/Failure/In-progress) and failure attribution.</li>\n</ol>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-scenegraph.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: SceneGraph as Context: Fusion of continuous multi-modal observations from sensors and action results confirmed by evaluators into a unified symbol Scene graph, generating a streamlined briefing (Brief) that is refreshed in rounds and injected into the context, supporting on-demand in-depth queries.</a>\n<figcaption>SceneGraph as Context: Fusion of the sensor’s continuous multi-modal observation and the action results confirmed by the evaluator into a unified symbol Scene graph, generating a streamlined briefing (Brief) that is refreshed and injected into the context in rounds, and supports on-demand in-depth query</figcaption>\n</div>\n<h4 id=\"-逐模块讲解-1\">② Explain module by module</h4>\n<ul>\n<li><strong>SceneGraph as Context (readability of world state)</strong>\n<ul>\n<li><strong>Input</strong>: RGB image, depth map, LiDAR point cloud, and robot pose reported by the underlying odometer.</li>\n<li><strong>processing</strong>: The system uses the perception pipeline to discretize the continuous physical space into a dynamic graph structure containing the object center coordinates, 3D bounding box, visible confidence and spatial topological relationships (such as <code class=\"language-plaintext highlighter-rouge\">on(bowl, table)</code>, <code class=\"language-plaintext highlighter-rouge\">near(robot, table)</code>, <code class=\"language-plaintext highlighter-rouge\">holding(gripper, cup)</code>); only after passing through the evaluator Only the action results that are confirmed to be truly successful (Confirmed) will be written into the topological relationship changes of the graph.</li>\n<li><strong>output</strong>: Before each round of decision-making, the graph is refined into a high-level structured brief (Scene graph brief) and pushed into the refreshed context (Refreshed context); the model can also call tools on demand through reference ID (Ref-keyed queries) to query the historical high-definition snapshots and detailed geometric properties of a specific object.</li>\n<li><strong>Design motivation</strong>: Completely solve the problem of context being overwhelmed by massive continuous video/image tokens in long-term multi-round interactions, and give large models the ability to understand scenes similar to “reading the project code structure tree”.</li>\n</ul>\n</li>\n<li><strong>Evaluation as Exit Codes (Judgment of action results)</strong>\n<ul>\n<li><strong>trigger mechanism</strong>: Harness forces structured triggering through the built-in post-hook after each operation is executed, depriving the underlying execution strategy of the right to “self-evaluate and boast”.</li>\n<li><strong>Processing</strong>: evaluator It only receives the visual observation at the current moment and the post-condition declared by the tool, which is completely independent of the high-level decision-making model; it outputs three-state judgments - <code class=\"language-plaintext highlighter-rouge\">Success</code> (success), <code class=\"language-plaintext highlighter-rouge\">Failure</code> (failure with detailed causal explanation, such as “not grasped due to end offset”, “target blocked by drawer”), <code class=\"language-plaintext highlighter-rouge\">In-progress</code> (the action is still progressing for a long time and has not timed out).</li>\n<li><strong>output</strong>: Package the verdict and failure attribution into the exit code response and inject the conversation history for the decision-making model to perform targeted retry or solution switching.</li>\n</ul>\n</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-evaluator-exit-codes.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Evaluation as Exit Codes triggering sequence: the model calls the Tool execution strategy. After the execution, the Harness post-hook actively triggers the independent Evaluator, and outputs a three-state judgment with the failure reason and feeds it back to the model.</a>\n<figcaption>Evaluation as Exit Codes Trigger timing: The model calls the Tool execution strategy. After the execution is completed, the Harness post hook actively triggers the independent Evaluator, and outputs a three-state judgment with the failure reason and feeds it back to the model</figcaption>\n</div>\n<h4 id=\"-卡点降维与理论推导\">③ Dimensionality reduction and theoretical derivation of stuck points</h4>\n<p><strong>stuck point 1: How do software Harness and embodied physical Harness correspond?</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>Software Engineering Agent (such as Claude Code / SWE-agent)</th>\n<th>Traditional robot control (single VLA/teaching playback)</th>\n<th>Embodied Physics Harness (Thea)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>status carrier</strong></td>\n<td>File system directory tree, AST, text code</td>\n<td>Instantaneous single frame/multi frame continuous camera image pixels</td>\n<td><strong>SceneGraph as Context</strong> (persistent 3D topology symbol Scene graph)</td>\n</tr>\n<tr>\n<td><strong>action output</strong></td>\n<td>Terminal Shell Commands, File Editing Patch</td>\n<td>Continuous joint angles/end 6-DoF track points</td>\n<td>Semantic Tool encapsulated as standardized pre/post Hook (such as <code class=\"language-plaintext highlighter-rouge\">grasp(ref)</code>)</td>\n</tr>\n<tr>\n<td><strong>Execution feedback</strong></td>\n<td>Operating system return code (Exit 0 / 1), Stack Trace</td>\n<td>There is no feedback. Once the action is over, you will blindly proceed to the next step.</td>\n<td><strong>Evaluation as Exit Codes</strong> (three-state decision + structured failure diagnosis reason)</td>\n</tr>\n<tr>\n<td><strong>Error correction mechanism</strong></td>\n<td>Read the error log, rewrite the code and recompile</td>\n<td>There is no way to correct the error. After catching a short shot, I will run through the subsequent long sequence empty-handed.</td>\n<td>Read in the failure attribution, fine-tune the pose and try again or actively search for hidden targets</td>\n</tr>\n</tbody>\n</table>\n<p><strong>stuck point 2: Why is it said that “the upper limit of Harness is determined by its evaluator accuracy $\\alpha$”?</strong></p>\n<p>In a long-term multi-step embodied task, assuming a task contains $n$ sequential stages, the single-step success rate is $p_i$.</p>\n<ul>\n<li>In traditional open-loop mode, task success requires that every step must succeed:\n\\(P_{\\text{open}} = \\prod_{i=1}^n p_i\\)</li>\n<li>When $n$ is large (such as $n=5$), even if the single-step success rate is as high as $p=0.8$, the total success rate will quickly degrade to $0.8^5 \\approx 32.8\\%$.</li>\n</ul>\n<p>Thea introduces a detect-retry loop with a maximum retry count of $k$. The evaluator makes a correct judgment with an accuracy of $\\alpha$ and a wrong judgment with an accuracy of $1-\\alpha$. The paper strictly proves that because the evaluator has <strong>false negatives</strong> (misjudgment of true success as failure, resulting in redundant retries that damage the results) and <strong>false positives</strong> (misjudgment of failure as success, resulting in downward penetration of errors), the net pass reliability of each step of the system is directly determined by $\\alpha$ Locked:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    Exec[\"Execute single step action Attempt\"] --&gt; Eval{\"independent evaluator judgment (Accuracy α)\"}\n    Eval -- \"The verdict is Success (Contains true success p*α with false positives (1-p)*(1-α))\" --&gt; Pass[\"Release to next stage\"]\n    Eval -- \"The verdict is Failure (Contains true failure (1-p)*α with false negatives p*(1-α))\" --&gt; RetryCheck{\"Current attempts &lt; k ?\"}\n    RetryCheck -- \"Yes\" --&gt; Diagnose[\"parse Failure attribution -&gt; Adjust strategy and try again\"]\n    Diagnose --&gt; Exec\n    RetryCheck -- \"No\" --&gt; Abort[\"Step budget limit reached -&gt; Declare task failure and termination\"]\n</code></pre>\n<blockquote>\n<p><strong>gives an example (specific number of reliability doubling)</strong>:\nAssume a long-term delivery task of $n=5$ steps, and the success rate of the underlying strategy at each step is $p=0.8$:</p>\n<ul>\n<li><strong>open-loop running</strong>: the total success rate is only $0.8^5 = 32.8\\%$;</li>\n<li><strong>Thea closed-loop (evaluator precision $\\alpha=0.95$, allowed to retry $k=3$ times)</strong>: The effective reliability of a single step under retry and precise release jumps to $97.6\\%$, and the total success rate of the entire 5-step task reaches $0.976^5 \\approx 88.5\\%$ achieves a task-level reliability gain of nearly 3 times that of !</li>\n</ul>\n</blockquote>\n<hr/>\n<h3 id=\"3-核心结果发现-2\">3. Results and findings</h3>\n<p>Thea has carried out comprehensive real-life physical experimental verification on diverse hardware platforms (Unitree G1 humanoid robot, Astribot S1 flexible humanoid robot, AgileX Cobot Magic wheeled dual-arm collaborative robot).</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-task-complexity-scaling.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of task success rates across different difficulty levels (L1 basic operations, L2 spatial combination, L3 long-term long-distance multi-stage interaction): As the number of task steps increases, the baseline model drops off a cliff, while Thea maintains excellent robustness</a>\n<figcaption> Comparison of task success rates across different difficulty levels (L1 basic operations, L2 spatial combination, L3 long-term long-distance multi-stage interaction): As the number of task steps increases, the baseline model drops off a cliff, while Thea maintains excellent robustness</figcaption>\n</div>\n<h4 id=\"-随任务复杂度扩展的绝对优势\">① Absolute advantages that scale with task complexity</h4>\n<p>The evaluation divided the tasks into three levels: L1, L2, and L3 according to time course and stage complexity, and compared mainstream single or layered baselines such as ACT, $\\pi_{0.5}$, LingBot-VLA-V2, CaP-X, and SayCan:</p>\n<ul>\n<li><strong>L1 base layer (short-term single step)</strong>: There is not much difference between each baseline and Thea, and the success rate is between 80% and 95%;</li>\n<li><strong>L2 Advanced level (including space rearrangement and multi-step dependency)</strong>: The single strategy begins to experience trajectory drift and short-sucking disorder, the success rate drops to 55%~80%, Thea reaches <strong>90%</strong>;</li>\n<li><strong>L3 Ultimate layer (cross-room long-distance navigation + drawer opening retrieval + target object grasping and delivery)</strong>: Single model (such as $\\pi_{0.5}$, LingBot) plummeted to <strong>40%</strong> due to accumulated error, SayCan Due to the lack of fine-grained geometry and closed-loop verification, it is only 53%, while Thea maintains a success rate of <strong>87%</strong> with closed-loop retries and Scene graph memory.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-emergent-capabilities.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Diversified physical intelligence behaviors that emerged driven by Thea: (a) autonomously draw power across rooms and deliver power banks; (b) actively open drawers for hierarchical retrieval when the target is not seen; (c) fine-tune poses for secondary grasping based on the failure reasons fed back by the evaluator; (d) proactively initiate human-machine dialogue to negotiate alternatives when the target drink is out of stock; (e) seamless migration of a single set of Harness across three completely different robot embodiments</a>\nThe diverse physical intelligent behaviors that emerged driven by<figcaption>Thea: (a) autonomously draw power across rooms and deliver power banks; (b) actively open drawers for hierarchical retrieval when the target is not seen; (c) fine-tune the pose for secondary grasping based on the failure reasons fed back by the evaluator; (d) actively initiate human-machine dialogue to negotiate alternatives when the target drink is out of stock; (e) a single set of Harness across three completely different robots Seamless migration</figcaption>\n</div>\n<h4 id=\"-闭环涌现出的高级物理行为\">② Advanced physical behaviors emerging from closed-loop</h4>\n<p>Thanks to the dynamic closed-loop orchestration of tools by the general Harness architecture, the robot exhibits several high-order emergent behaviors that could not be achieved by the previous single model:</p>\n<ul>\n<li><strong>Active Perception</strong>: When the power bank is not retrieved in the Scene graph, the model actively plans the detection link of “navigate to the counter → call the drawer pull tool → tilt the wrist camera to observe the inner layer of the drawer”;</li>\n<li><strong>Targeted fault diagnosis and correction (Diagnosed Recovery)</strong>: When the grasping can slips due to too far distance, the evaluator returns <code class=\"language-plaintext highlighter-rouge\">“Fail: target slipped due to hand clearance offset”</code>, and the model actively generates <code class=\"language-plaintext highlighter-rouge\">reposition(base, delta=[-0.05, 0])</code> in the next round. After adjusting the micro distance of the base, grasping is successful again;</li>\n<li><strong>Human-computer collaborative interaction (User Clarification)</strong>: When the user requests the delivery of specific mineral water but only juice and tea are available on the desktop, the Agent autonomously suspends physical execution and asks the user questions to negotiate alternatives through the mobile phone interface.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-2\">4. Limitations</h3>\n<ol>\n<li><strong>Scene graph maintenance computational overhead and latency bottleneck</strong>: As the indoor exploration space continues to expand, the computational overhead of 3D instance point cloud segmentation and real-time topology map merging increases significantly, which may lead to significant lags in round decision-making;</li>\n<li><strong>Risk of misjudgment of the evaluator under three-dimensional occlusion and extreme deformation</strong>: The evaluator relies on visual feedback from a single perspective or a hand-eye camera. Misjudgment may still occur under strong reflection, small object occlusion or extreme lighting conditions. Once a misjudgment occurs, it will directly limit the final reliability of the system.</li>\n</ol>\n<hr/>\n<h2 id=\"zetta\">4. Zetta (2026)</h2>\n<p>———An Efficient Closed-Loop Embodied Harness for Self-Evolving Physical Intelligence</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2608.16590\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2608.16590</a> · <a href=\"https://air-embodied-brain.github.io/zetta\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-3\">Key takeaways</h3>\n<ul>\n<li><strong>proposes an embodied closed-loop Harness for self-evolution physical intelligence</strong>: Aiming at the dilemma that end-to-end single VLA/WAM lacks micro-correction during execution and traditional post-hoc reflection (Post-hoc Reflection) is difficult to attribute high-frequency physical interactions, a self-evolution system Zetta is built that integrates high-frequency online judgeing, in-situ exception recovery and offline skill distillation.</li>\n<li><strong>Structured evolvable Harness abstraction ($H = {C, R, T}$)</strong>: Keep the underlying motion strategy frozen with the high-level orchestration commander, and define Harness decoupling as a runtime judge collection $C$, a recovery action library $R$, and a heterogeneous toolset $T$. The physical trial and error experience is directly distilled into parameterized code modules, which evolve autonomously with the interaction rounds.</li>\n<li><strong>Top-down minimal intervention hierarchical causal diagnosis</strong>: Establish the core principle of “if the high-level logic can be solved, never change the underlying parameters”, conduct top-down investigation according to priority (evaluation → judge → status → planning → recovery → parameters) to prevent generalization collapse caused by overfitting to a single use case.</li>\n<li><strong>Discovering the Robotic “Aha Moment” of Embodied Physical Intelligence</strong> : Reveals the objective law of the nonlinear transition of embodied self-evolution - the initial repair of the appearance keeps the performance at a low plateau. Once the root cause is located and the key “judge-recovery” closed-loop mechanism is evolved, the task success rate shows an instant vertical increase (such as a sudden surge from 10% to 95%).</li>\n<li><strong>High-throughput infrastructure with decoupled software and hardware Z-Infra</strong>: Design a multi-node heterogeneous concurrent infrastructure, decouple the environment from the model computing pool, achieve an effective sampling throughput of up to 35.1 episodes/min (20.6 times improvement), and significantly shorten the inference delay by 91%, strongly supporting large-scale closed-loop self-evolution.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-3\">1. Background and problem</h3>\n<p>Although Vision-Language-Action (VLA) and World Action Model (WAM) have made significant progress in large-scale data pre-training, they are still highly fragile when deployed in the physical world. The root cause is: <strong>The physical environment is a continuous system</strong> that evolves at high frequency at the millisecond level. If an object slips slightly, the desktop reaction force is unbalanced, or a small contact disturbance is not sensed and corrected at the moment of occurrence, it will quickly trigger a compound error cascade, eventually leading to the collapse of the global task.</p>\n<p>In order to overcome this bottleneck, in recent years, academic circles have tried to introduce multi-modal Agents for “Post-hoc Reflection”. However, traditional reflection mechanisms face insurmountable theoretical and engineering obstacles in embodied physical scenarios:</p>\n<ol>\n<li><strong>Credit Assignment Problem (Credit Assignment Problem)</strong>: A long-term operation failure involves hundreds or thousands of continuous control steps. Afterwards, the large model is asked to reflect in detail. The model cannot accurately infer which tiny declination angle of the wrist in the few seconds caused the disaster;</li>\n<li><strong>Lack of on-site online verification environment</strong>: The corrective hypothesis generated by post-mortem reflection can only be tested after the next complete re-run, which is extremely inefficient and easily misleading;</li>\n<li><strong>Patching causes over-fitting (Over-Parameterized Repair)</strong>: In the past, manual tuning or simple parameter tuning often forcibly modified the underlying control parameters for specific failed use cases, which not only destroyed the global semantic understanding and generalization distribution of the base VLA, but also caused catastrophic performance degradation in unseen environments and new random seeds.</li>\n</ol>\n<p><strong>Core question</strong>: How to build an embodied closed-loop Harness that does not need to modify the underlying policy parameters, can achieve high-frequency micro online correction, and can automatically sublimate failed physical experience and continue to evolve autonomously?</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-3\">2. Methods and innovations</h3>\n<p>Zetta proposes a dual-loop physical intelligence system that integrates online high-frequency governance <strong>and offline autonomous evolution</strong>. Together with the hardware-decoupled high-throughput concurrent infrastructure Z-Infra, it achieves self-propagation and robust evolution of physical strategies.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Zetta self-evolution embodied Harness panorama: high-frequency runtime judge leads the online action error correction loop, offline evolution Agent clusters failure trajectories and distills reusable skills, and cooperates with the decoupled infrastructure Z-Infra to drive throughput doubling and \"aha moment\"</a>\n<figcaption>Zetta self-evolution Embodied Harness Panorama: High-frequency running time, the judge leads the online action error correction loop, offline evolution Agent clusters failure trajectories and distills reusable skills, and cooperates with the decoupled infrastructure Z-Infra to drive throughput doubling and \"aha moment\"</figcaption>\n</div>\n<h4 id=\"-整体框架与双环运行机制\">① Overall framework and double-loop operating mechanism</h4>\n<p>Zetta clearly divides the system into two immutable entities and a core evolution carrier:</p>\n<ul>\n<li><strong>Two immutable entities</strong>: underlying action strategy $\\pi$ (frozen VLA/WAM parameters, $\\nabla_\\theta = 0$) and high-level orchestration Agent $A_{orch}$ (multimodal decision operator, constant decision logic);</li>\n<li><strong>core evolution carrier Harness ($H = {C, R, T}$)</strong>:\n    <ul>\n<li><strong>Runtime Critics ($C$)</strong>: A high-frequency monitoring function that runs higher than the low-level action strategy, continuously scans real-time trajectory fragments and generates proposals with fault evidence and status suggestions \\(P_t = \\langle e_t, \\hat{\\sigma}_t \\rangle\\);</li>\n<li><strong>Recovery Action Library (Recovery Playbook, $R$)</strong>: A collection of parameterized micro-actions targeting specific fault causal mechanisms;</li>\n<li><strong>Heterogeneous Toolset ($T$)</strong>: motion planner, 6-DoF grasping generator (GraspGen) and placement stabilizer.</li>\n</ul>\n</li>\n</ul>\n<p>The operation of the system is divided into <strong>online parallel Rollout</strong> and <strong>offline Reflection &amp; Evolve evolution cycle</strong>:</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-evolution-framework.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Zetta evolution framework three-stage process: online concurrent collection of success and failure trajectories, offline Harness update through failure portrait clustering (Phase I), hierarchical causal diagnosis and repair (Phase II), and cross-task generalization merging (Phase III)</a>\n<figcaption>Zetta evolution framework three-stage process: online concurrent collection of success and failure trajectories, offline update through failure portrait clustering (Phase I), hierarchical causal diagnosis and repair (Phase II), and cross-task generalization merging (Phase III) Harness</figcaption>\n</div>\n<h4 id=\"-逐模块讲解-2\">② Explain module by module</h4>\n<ul>\n<li><strong>Phase I: Failure Profiling</strong>\n<ul>\n<li><strong>input</strong>: a collection of failed trajectories collected concurrently by multiple threads, and the corresponding nominal success reference trajectory (Nominal baseline).</li>\n<li><strong>processing</strong>: Slice the failed trajectories according to the physical stages of task advancement (pre-contact approach, grasping closure, spatial transportation, placement and release), and use the successful trajectories as the benchmark to cluster common instability modes.</li>\n<li><strong>outputs</strong>: a structured failure portrait list, pinpointing the common stage distribution of multiple failures.</li>\n</ul>\n</li>\n<li><strong>Phase II: Hierarchical causal diagnosis and minimal intervention repair (Diagnosis &amp; Repair)</strong>\n<ul>\n<li><strong>Top-down diagnostic level</strong>: Strictly follow the six-level priority investigation:\n\\(\\text{Evaluation} \\to \\text{Critic} \\to \\text{State} \\to \\text{Planning} \\to \\text{Recovery} \\to \\text{Parameter}\\)</li>\n<li><strong>Design Motivation</strong>: Give priority to solving problems by adding pre-aligned critics at high levels or calling geometric planning tools; it is strictly prohibited to directly dive into tampering with the joint stiffness of the underlying motor or fine-tune the low-level weights to maximize the broad generalization of the base model.</li>\n<li><strong>Validation Guard</strong>: Each code-level fix patch generated must be retested in-place on the same random seed that caused the failure, and submission is only allowed if it passes validation (Validate Passed).</li>\n</ul>\n</li>\n<li><strong>Phase III: Harness Generalization and Merger (Harness Generalization)</strong>\n<ul>\n<li><strong>processing</strong>: Promote the specific seed patch that has passed verification into a universal judge and recovery logic with abstract parameters, perform conflict-free merging across use cases, package and generate versioned $H_{merged}$, and hot-reload it to the online environment.</li>\n</ul>\n</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-critic-recovery-sequence.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Record of judge-recovery cascade intervention in a single rollout: when an object is detected to be off during transportation, re-approach is immediately triggered, when an invalid posture is detected, GraspGen is called to generate the posture, and in the final stage, smooth placement recovery is called</a>\n<figcaption> Record of judge-recovery cascade intervention in a single rollout: when an object is detected to be off during transportation, re-approach is immediately triggered, when an invalid posture is detected, GraspGen is called to generate the posture, and in the final stage, smooth placement recovery is called</figcaption>\n</div>\n<h4 id=\"-卡点降维与自制架构图\">③ Card point dimensionality reduction and self-made architecture diagram</h4>\n<p><strong>stuck point 1: Why can’t physical interaction be solved by post-mortem reflection? How exactly does Zetta’s microscopic closed-loop work?</strong></p>\n<p>We clearly present the decoupled collaboration of Zetta’s online millisecond-level interception and offline minute-level self-evolution through the Mermaid double-loop mechanism diagram:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    subgraph Online [\"Online high-speed execution loop (millisecond level)\"]\n        Obs[\"Real-time sensor observations s_t\"] --&gt; Policy[\"freeze action strategy π (VLA)\"]\n        Policy --&gt; Action[\"Predictive control actions a_t\"]\n        Action --&gt; Critic{\"High frequency runtime judge C Monitor\"}\n        Critic -- \"Nominal normal (Nominal)\" --&gt; Exec[\"Physical execution of actions\"]\n        Critic -- \"trigger exception (Slip/Collision)\" --&gt; Intervene[\"Suspend action, call Recovery R\"]\n        Intervene --&gt; Tool[\"Toolset T (Such as GraspGen / Re-approach)\"]\n        Tool --&gt; Exec\n        Exec --&gt; StatusCheck{\"determine the Episode Is it over??\"}\n        StatusCheck -- \"Not over\" --&gt; Obs\n        StatusCheck -- \"success/failed\" --&gt; Buffer[\"Save to track storage pool\"]\n    end\n\n    subgraph Offline [\"Offline evolving self-healing loop (Minute level)\"]\n        Buffer --&gt; Cluster[\"Phase I: Failure trajectory clustering and stage slicing\"]\n        Cluster --&gt; Diagnosis[\"Phase II: top-down causal diagnosis (E -&gt; C -&gt; S -&gt; P -&gt; R)\"]\n        Diagnosis --&gt; Patch[\"Synthesis reusable Critic / Recovery Skill code\"]\n        Patch --&gt; Test{\"Validation guard: Original failed seed retest verification\"}\n        Test -- \"Verification passed\" --&gt; Generalize[\"Phase III: Abstract and merge to generate a new version H_merged\"]\n        Generalize --&gt; Online\n    end\n</code></pre>\n<p><strong>stuck point 2: What is the “Aha Moment” of embodied physical intelligence?</strong></p>\n<p>In the process of embodied self-evolution, many readers easily mistakenly believe that the success rate of the strategy will increase uniformly and linearly with the amount of interactive data. Zetta reveals a very physically inspiring phenomenon:</p>\n<table>\n<thead>\n<tr>\n<th>Evolution stage</th>\n<th>Repair strategy type</th>\n<th>typical behavior</th>\n<th>Success rate performance</th>\n<th>essential reason</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Round 0 (initial)</strong></td>\n<td>Pure Freeze VLA open-loop run</td>\n<td>Grabbing air, sliding, and hard collision between the end and the table</td>\n<td>0% ~ 15% (very low)</td>\n<td>Lack of any physical interaction feedback</td>\n</tr>\n<tr>\n<td><strong>Round 1 (Initial exploration)</strong></td>\n<td><strong>Symptomatic Fixes</strong> (Symptomatic Fixes)</td>\n<td>Relax the time budget, increase the number of retries, and increase the clamping jaw closing threshold</td>\n<td>5% ~ 15% (<strong>stagnation plateau period</strong>)</td>\n<td>The root cause of physical failure has not been touched, and errors still occur during transportation.</td>\n</tr>\n<tr>\n<td><strong>Round 2 (moment of enlightenment)</strong></td>\n<td><strong>Root-Cause Repair</strong> (Root-Cause Repair)</td>\n<td>Evolved <code class=\"language-plaintext highlighter-rouge\">Pre-grasp Staging</code> (front space posture alignment) and <code class=\"language-plaintext highlighter-rouge\">Grasp Retention Critic</code> (slip-off high-frequency interception)</td>\n<td><strong>instantly soared to 90% ~ 95%</strong></td>\n<td>Completely solves the line of sight obstruction and initial normal vector misalignment when the robotic arm reaches down.</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Give an example (the epiphany deduction of putting a red wine bottle into a deep dish)</strong>:\nThe task requires a robotic arm to place an upright red wine bottle smoothly onto a plate.</p>\n<ul>\n<li><strong>Stage 1 (Pure VLA)</strong>: Pounces directly towards the bottleneck, frequently knocking over wine bottles due to reflection and perspective deviation, the success rate is only 5%;</li>\n<li><strong>Phase 2 (Trying to cure the symptoms)</strong>: Evolution Agent tries to make the robot arm quickly retreat after grasping fails and increase the speed to try again. However, the bottle has been knocked crooked, and the next descent will inevitably miss the target again. The success rate is always hovering around 10%;</li>\n<li><strong>Stage 3 (Aha Moment)</strong>: Evolution Agent finally discovered the fundamental contradiction through causal diagnosis - “The bottle body is slender. If a pre-aligned posture is not established from the side, direct dive will inevitably touch the mouth of the bottle.” So Zetta automatically synthesized two collaborative mechanisms:\n      <ol>\n<li><code class=\"language-plaintext highlighter-rouge\">Pregrasp Staging</code>: The robotic arm first hovers 5cm directly in front of the bottle and flattens the wrist;</li>\n<li><code class=\"language-plaintext highlighter-rouge\">Retention Critic</code>: Monitor the terminal inclination angle in real time during the lifting process, and immediately decelerate and fine-tune it once it slips.\nAfter the patch is loaded, the success rate of this task changes from <strong>10% jumps to 90%</strong> , truly crossing the physical bottleneck!</li>\n</ol>\n</li>\n</ul>\n</blockquote>\n<hr/>\n<h3 id=\"3-核心结果发现-3\">3. Results and findings</h3>\n<p>Zetta conducted system evaluations on the international common embodied operation benchmark LIBERO-Pro and the RoboCasa kitchen long-term benchmark, and conducted comprehensive comparisons with the latest end-to-end baselines and Agent systems.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-aha-moments.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The “Aha Moment” of physical intelligence on LIBERO-Pro: Initial temporary fixes caused performance to stagnate for a long time. Once the root cause is located and the key judge-recovery mechanism is generated, the success rate increases dramatically.</a>\nThe \"Aha Moment\" of physical intelligence on<figcaption>LIBERO-Pro: The initial temporary fix caused the performance to stagnate for a long time. Once the root cause is located and the key judge-recovery mechanism is generated, the success rate increases sharply</figcaption>\n</div>\n<h4 id=\"-卓越的任务成功率与自演化扩展性\">① Excellent task success rate and self-evolution scalability</h4>\n<ul>\n<li><strong>LIBERO-Pro simulation benchmark</strong>: In the most challenging perturbation test, the success rate of the pure $\\pi_{0.5}$ strategy was only 34.5%, while Zetta went through several rounds of autonomous closed-loop evolution and finally significantly increased the success rate to <strong>90.8%</strong>;</li>\n<li><strong>RoboCasa virtual kitchen benchmark</strong>: In the complex long-term hinge cabinet door opening, kitchen appliance operation and item organization tasks, the success rate of the base model GR00T is 73.6%. After Zetta’s independent evolution, it reaches the ultra-high level of <strong>93.6%</strong>;</li>\n<li><strong>Endless evolutionary gains</strong>: Experiments have proven that with the accumulation of concurrent rollout experience pool, the self-evolution curve continues to rise, completely breaking the performance deadlock of traditional fixed strategies under data bottlenecks.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-cross-task-scaling.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Cross-task zero-sample skills transfer verification: The pre-grasping, grasping retention and retry skill stacks precipitated in the source task (Goal-T8 red wine bottle operation) have been implemented on unseen target tasks (Goal-T2, T6, S3) without fine-tuning plug-and-play migration.</a>\n<figcaption> Cross-task zero-sample skills transfer verification: The pre-grasping, grasping retention and retry skill stacks precipitated in the source task (Goal-T8 red wine bottle operation) are implemented on the unseen target tasks (Goal-T2, T6, S3) without fine-tuning plug-and-play migration</figcaption>\n</div>\n<h4 id=\"-零样本跨任务技能迁移\">② Zero-sample cross-task skill transfer</h4>\n<p>The Critic and Recovery skills learned through evolution on a single task are not islands of overfitting, but have strong physical versatility:</p>\n<ul>\n<li>In the alignment approach, drop re-grab and buffer placement skill stack evolved on RoboCasa’s <code class=\"language-plaintext highlighter-rouge\">PnP-Stove</code> (stove pick and place), when the zero sample is migrated to the sink (<code class=\"language-plaintext highlighter-rouge\">PnP-Sink</code>) task, the success rate jumps directly from 58% to <strong>82%</strong>; from 62% to <strong>80%</strong> when migrating to cabinets (<code class=\"language-plaintext highlighter-rouge\">PnP-Cabinet</code>); from 72% to when migrating to toasters (<code class=\"language-plaintext highlighter-rouge\">PnP-Toaster</code>) <strong>90%</strong>.</li>\n</ul>\n<h4 id=\"-z-infra-带来的工程效率质变\">③ Qualitative changes in engineering efficiency brought about by Z-Infra</h4>\n<ul>\n<li><strong>throughput increased by 20.6 times</strong>: By decoupling environment simulation nodes and model inference resource pools, Z-Infra increased the effective trajectory sampling throughput from 1.7 episodes/min to <strong>35.1 episodes/min</strong> under 64 concurrency, significantly ahead of the existing baseline. 7.7~12.8 times;</li>\n<li><strong>delay is significantly reduced by 91%</strong>: The end-to-end decision-making delay is reduced by 91% (up to 11.1 times faster), completely eliminating the delay shackles of large model Agents participating in physical real-time closed-loop from the engineering base.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-3\">4. Limitations</h3>\n<ol>\n<li><strong>relies on the resetability of the emulator or digital twin.</strong>: Offline autonomous evolution requires multiple in-place replays and patch verifications for failed random seeds. Currently, it performs most smoothly in simulation and high-precision digital twin environments with resettable characteristics. It is still risky to carry out independent trial and error in purely realistic physical scenarios with completely irreversible damage;</li>\n<li><strong>Search boundary for automatic synthesis of high-frequency critic code</strong>: When faced with highly nonlinear, non-rigid and extremely complex fluid or cloth operations, the automatically generated heuristic critic and recovery action space are difficult to exhaust all dynamic physical boundaries.</li>\n</ol>\n<hr/>\n<h2 id=\"show-harness\">5. Show-Harness (2026)</h2>\n<p>———Just a VLM Agent Can Play Robots</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.10522\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.10522</a> · <a href=\"https://showlab.github.io/Show-Harness\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-4\">Key takeaways</h3>\n<ul>\n<li><strong>proposed Embodied Harness’s “semantic action unit” interface</strong>: rewrite the robot control into a set of discrete, interpretable semantic symbols (<code class=\"language-plaintext highlighter-rouge\">MV_FWD</code> / <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> / <code class=\"language-plaintext highlighter-rouge\">GRASP</code>…), VLM only spits out one symbol at each step, and then the embodiment The dedicated interpreter deterministically completes a small segment of real motion - the semantics of <strong>are left to the model, and the metrics are left to the interpreter</strong>. The two sides are completely decoupled, and the model is therefore always responsible for fine-grained physical decisions.</li>\n<li><strong>The same interface feeds the computing power of both ends at the same time</strong>: Closed-source cutting-edge VLM can directly start the robot with zero samples (Cross-Task 89.0%); 2B open source small model can learn the same set of action vocabulary (86.0%) using rank-64 LoRA and single card H200 within two hours of fine-tuning. The key lies in the semantic action prediction based on the VLM native vocabulary. <strong>does not add action headers and does not add special token</strong>.</li>\n<li><strong>“Symbol + Increment” brings no-retraining adaptability</strong>: When changing the accuracy, only the interpreter step size is changed (2 cm→1 cm, ZS 60%→80%), when changing the robot, only the interpreter is changed, and the unseen 90° rotation relies on extrapolation of 15° unit combinations repeated 6 times (70% vs $\\pi_{0.5}$’s 20%), the model parameters remain unchanged throughout the process.</li>\n<li><strong>reveals that the real source of interface effectiveness is “plain text convention” rather than symbol name</strong>: 2×2 ablation shows that arbitrary symbols A–F are paired with direction conventions and still 95%, while only giving symbols without conventions plummets to 5%; the direction mapping inferred by the model’s own trial is only 23.3% correct (16.7% random), and the left and right directions on the confusion matrix mirror each other in large areas.</li>\n<li><strong>GUMI: A data acquisition interface that exposes action words lists as web page buttons</strong>: Human keyboard, computer-use agent clicks on the same web page, and universal VLM directly predicts symbols. The three share the same action space; no dedicated remote operation hardware is required, and one demonstration can train semantic action strategies and continuous control strategies at the same time, and naturally supports cross-embodiment reuse and human-computer hybrid acquisition.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-4\">1. Background and problem</h3>\n<p>The basic VLM has actually installed most of the knowledge required for robot operation (recognizing objects, judging spatial relationships, and dismantling long-horizon targets), but this knowledge does not fall on the joints. The existing two paths have their own costs: VLA fine-tunes VLM into a continuous action regressor, and the semantics are compressed into an uninterpretable “pixel → driver” mapping. When changing tasks, environments, or embodiments, data must be collected again; hierarchical/skill library-based agents allow VLM to only issue sub-goals or adjust skills, and the physical implementation is left to the downstream controller. The model “says it but does not see how to do it”, and each intermediate representation is tied to a carefully engineered grounding pipeline.</p>\n<p>The author’s judgment is: what is missing is not model capacity, but a <strong>It is both friendly to VLM semantics and detailed enough to directly control the physical action space.</strong> .</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-4\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Show-Harness uses a set of semantic action interfaces to connect cutting-edge VLM to different robot embodiments: the model only outputs symbols such as MV_RIGHT, and the action interpreter is responsible for safety boundaries and step sizes, and then translates them into respective underlying instructions.</a>\n<figcaption>Show-Harness uses a set of semantic action interfaces to connect the cutting-edge VLM to different robot embodiments: the model only outputs symbols such as MV_RIGHT, and the action interpreter is responsible for the safety boundary and step size, and then translates them into the underlying instructions of the respective embodiments</figcaption>\n</div>\n<h4 id=\"-整体框架概述-3\">① Overview of the overall framework</h4>\n<p>Show-Harness consists of three parts: <strong>semantic action interface</strong> (action vocabulary faced by the model \\(\\mathcal A\\)), <strong>embodiment interpreter</strong> (deterministically translate symbols into robot motion), <strong>Embodied Harness Plug-in loop</strong> (organizes perception-reasoning-action into a configurable closed-loop). In addition, it is equipped with <strong>GUMI</strong> - a data collection interface that exposes the same set of action words as web buttons. One sentence summarizes the data flow: multi-view images and embodiment states are first organized into context by the perception plug-in. The reasoning plug-in splits the task into visually verifiable sub-tasks and determines the step size for this step. Based on this, VLM spits out <strong>and a</strong> semantic action unit. The interpreter converts it into a small displacement, and the execution results are reflowed into the next observation.</p>\n<h4 id=\"-语义动作接口模型只需要认-11-个符号\">② Semantic action interface: The model only needs to recognize 11 symbols</h4>\n<p>The action word list \\(\\mathcal A\\) is a compact set of semantic units:</p>\n<ul>\n<li><strong>translates</strong>: <code class=\"language-plaintext highlighter-rouge\">MV_FWD</code> / <code class=\"language-plaintext highlighter-rouge\">MV_BACK</code>, <code class=\"language-plaintext highlighter-rouge\">MV_LEFT</code> / <code class=\"language-plaintext highlighter-rouge\">MV_RIGHT</code>, <code class=\"language-plaintext highlighter-rouge\">MV_UP</code> / <code class=\"language-plaintext highlighter-rouge\">MV_DOWN</code>, the direction is defined relative to the currently selected reference perspective;</li>\n<li><strong>rotates</strong>: <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> / <code class=\"language-plaintext highlighter-rouge\">ROTATE_CCW</code>, each with a rotating axis ($x$ / $y$ / $z$);</li>\n<li><strong>jaws and termination</strong>: <code class=\"language-plaintext highlighter-rouge\">GRASP</code>, <code class=\"language-plaintext highlighter-rouge\">RELEASE</code>, <code class=\"language-plaintext highlighter-rouge\">DONE</code>.</li>\n</ul>\n<p>The author deliberately designed this vocabulary list around three properties:</p>\n<ol>\n<li><strong>Incremental</strong> - Each unit only causes a small and local physical change. The advantage is that the model always “stands in the loop”: it can see the effect of its previous step from the next frame and rely on continuous fine-tuning to approach accuracy, rather than planning an entire trajectory in one go.</li>\n<li><strong>is interpretable and embodiment-agnostic</strong> - the actions are symbols rather than numerical targets, the underlying control related to the embodiment is pushed to the downstream interpreter, and the space faced by the model is therefore fully reusable between different robots.</li>\n<li><strong>Vision can be anchored</strong> - the direction is defined relative to the observable perspective, and spatial reasoning can be directly mapped to action selection.</li>\n</ol>\n<h4 id=\"-本体解释器符号如何变成真实位移\">③ embodiment interpreter: how symbols become real displacements</h4>\n<p>Each decision \\(a_t \\in \\mathcal A\\) is handed over to the embodiment-specific interpreter \\(g_E\\), which maintains a 6-DoF Cartesian pose set point \\(s_t = (\\mathbf x_t, Q_t)\\) and updates it as follows:</p>\n\n\\[s_{t+1} = \\Pi_E\\big(\\mathbf x_t + \\sigma_t R_E d_a,\\ \\exp(\\theta_t [R_E r_a]_\\times)\\, Q_t\\big)\\]\n\n<p>Here, \\(d_a\\) and \\(r_a\\) respectively encode the translation direction and rotation axis (translation unit \\(r_a = 0\\), rotation unit \\(d_a = 0\\), and \\(r_a \\in \\{\\pm e_x, \\pm e_y, \\pm e_z\\}\\)); \\(\\sigma_t\\), \\(\\theta_t\\) It is the calibrated translation/rotation increment; \\(R_E\\) maps the semantic direction to the motion coordinate system of the embodiment $E$; \\([\\cdot]_\\times\\) is the antisymmetric matrix operator; the projection \\(\\Pi_E\\) enforces the workspace, desktop height and single-step amplitude limits, and out-of-bounds actions are blocked before execution. The gripper unit skips pose updates and is directly mapped to opening and closing commands.</p>\n<blockquote>\n<p><strong>gives an example (a complete landing process of MV_RIGHT)</strong>: VLM spits out <code class=\"language-plaintext highlighter-rouge\">MV_RIGHT</code>. The interpreter’s current set point position is \\(\\mathbf x_t = (0.40,\\ 0.00,\\ 0.25)\\) m. Look up the table and get \\(d_a = +e_y\\), \\(r_a = 0\\); Franka’s \\(R_E\\) maps “right relative to the reference perspective” to the base system \\(+y\\); the target has entered the wrist field of view, so use the fine step size \\(\\sigma_t = 0.02\\) m. The new position is \\((0.40,\\ 0.02,\\ 0.25)\\), and the posture does not move. \\(\\Pi_E\\) Check again: not out of the workspace and not lower than the desktop → Release. When he landed on the bottom floor, Franka used impedance control to follow the Cartesian set point, AgileX inverse kinematics + joint target flow, and the simulator issued an operating space command - the same <code class=\"language-plaintext highlighter-rouge\">MV_RIGHT</code>, which was “2 cm to the right” on the three systems. For a new robot, the only thing that needs to be written is this interpreter.</p>\n</blockquote>\n<h4 id=\"-和现有两条路线的差别\">④ Differences from the existing two routes</h4>\n<p>This step is the argument of the whole article, which can be best understood with a table:</p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>VLA(π0.5 / GR00T)</th>\n<th>Layering/skill library agent</th>\n<th>Show-Harness</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>What does VLM output?</td>\n<td>Continuous Action Blocks (Regression/Diffusion/Flow Matching)</td>\n<td>Subtask description or skill invocation</td>\n<td>a semantic action unit</td>\n</tr>\n<tr>\n<td>Who is responsible for fine-grained physics decisions?</td>\n<td>Model, but suppressed into unexplainable perceptual→driven mapping</td>\n<td>Downstream controller or VLA, process invisible to model</td>\n<td>The model itself, and you can see the results at every step</td>\n</tr>\n<tr>\n<td>What should I change when replacing a robot?</td>\n<td>Re-collect data + re-fine-tune</td>\n<td>Rewrite skill library and grounding pipeline</td>\n<td>Just change an interpreter</td>\n</tr>\n<tr>\n<td>What should be changed to improve accuracy requirements?</td>\n<td>Supplement a batch of fine motor data for retraining</td>\n<td>Depends on underlying controller capabilities</td>\n<td>Interpreter step size changed from 2 cm to 1 cm</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-embodied-harness九个插件如何串成一步\">⑤ Embodied Harness: How nine plug-ins are strung together in one step</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Show-Harness architecture: three sections of configurable plug-ins, namely perception, reasoning and action, form a closed-loop around the central VLM. Pink is the reasoning flow, green is the action flow, and the dotted box is the optional plug-in enabled on demand.</a>\n<figcaption>Show-Harness architecture: three sections of configurable plug-ins: perception-reasoning-action form a closed-loop around the central VLM. Pink is the reasoning flow, green is the action flow, and the dotted box is the optional plug-in  that is enabled on demand.</figcaption>\n</div>\n<p>The perception and reasoning plug-in processes the original observation into a “refined context” \\(c_t = \\Phi_{\\mathcal P}(\\ell, o_t, h_t)\\) ($\\ell$ is a language command, $o_t$ is a multi-perspective observation, and $h_t$ is an interaction history), and VLM selects the action \\(a_t = \\pi(c_t)\\) on this context. The division of labor among the nine plug-ins is as follows:</p>\n<p><strong>Perception (Perception)</strong></p>\n<ul>\n<li><strong>Multi-View Guidance</strong>: Tells VLM how to use each camera - global first/third person perspective for scene-level context, wrist perspective for detailed evidence of close alignment.</li>\n<li><strong>Proprioception</strong>: Translate the internal state of the robot into short text, including the height of the gripper from the table, how far it will go in a single step, phased prompts (descend first if it is still too high), contact status and the opening and closing status of the gripper.</li>\n</ul>\n<p><strong>Reasoning</strong></p>\n<ul>\n<li><strong>Subtask Planning</strong>: First let VLM act as the planner to split the instructions into ordered subtasks. Each subtask has a <strong>available image to directly check the completion criterion of</strong>; during execution, each step will be compared with the current image to determine whether it has been achieved. If it is not achieved, it will continue to be done. If it is achieved, it will be announced to advance.</li>\n<li><strong>Situated Planning</strong> (default off): Suspend <strong>for the branch decision</strong> that currently lacks information, and come back to solve it after the relevant evidence becomes visible during execution. It is suitable for conditional tasks such as “Which of the three cups is the block hidden in?” to avoid planning all branches at the beginning.</li>\n<li><strong>Action Chunking</strong>: When the target is still far away and fine-grained feedback is not needed, VLM is allowed to spit out a small series of actions at a time for open-loop execution, reducing the frequency of model calls.</li>\n<li><strong>Adaptive Step</strong>: Use a 2 cm fine step when the target appears in the wrist field of view, otherwise use a 4 cm coarse step.</li>\n<li><strong>Visual Prompt</strong> (off by default): Use a dedicated model call to convert the linguistically difficult-to-define goal of “grasping the cup handle” into a visual mark on the image, and subsequent inferences are directly anchored to this mark.</li>\n</ul>\n<p><strong>Action (Action)</strong></p>\n<ul>\n<li><strong>Action History</strong>: Bring the last 5 actions into the next step context, and attach a usage tip “Don’t swing back and forth between opposite directions” to provide lightweight memory for stepping.</li>\n<li><strong>Failure Recovery</strong>: Automatically detect grasping, reset the gripper state and roll back to the corresponding grasping subtask to start again.</li>\n</ul>\n<p>The order of these plug-ins in one-step interaction is as follows:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"observation: multi-view images + embodiment state\"] --&gt; B[\"Perception: Multi-View Guidance Division of labor + Proprioception Literalization\"]\n    B --&gt; C[\"Subtask Planning: Compare the image to determine whether the current subtask has been achieved\"]\n    C --&gt; D[\"Adaptive Step: Target is within wrist view? Small steps 2cm / rough steps 4cm\"]\n    D --&gt; E[\"VLM Output a semantic action unit\"]\n    E --&gt; F[\"Action History: write recently 5 step, Suppress back and forth oscillation\"]\n    F --&gt; G[\"Interpreter: symbol -&gt; 6-DoF Pose set point increment\"]\n    G --&gt; H[\"safe projection: workspace / Desktop height / Single step range upper limit\"]\n    H --&gt; I[\"Robot execution, Environment and execution status updates\"]\n    I --&gt; J[\"Failure Recovery: Shortage detection -&gt; Roll back to grasping subtask\"]\n    J --&gt; A\n</code></pre>\n<h4 id=\"-同一个接口两种用法\">⑥ The same interface, two usages</h4>\n<p><strong>ZS mode (frontier VLM zero sample as agent)</strong>: The closed-source frontier model does not require any fine-tuning and controls the robot directly through the harness. The advantage is that as subsequent models become stronger, the robot’s capabilities will automatically increase accordingly.</p>\n<p><strong>FT mode (fine-tuned open source small model)</strong>: The same set of action words can also be used to train small models. Given the demo \\(\\mathcal D\\) collected with the same action space, the policy minimizes the token-level cross-entropy of the target unit:</p>\n\n\\[\\min_{\\theta}\\ \\mathcal L(\\theta) = -\\sum_{(\\ell, o, h, a) \\in \\mathcal D} \\log \\pi_\\theta\\big(a \\mid \\Phi_{\\mathcal P_{\\min}}(\\ell, o, h)\\big)\\]\n\n<p>The \\(\\mathcal P_{\\min}\\) here is deliberately trimmed to the thinnest context (leaving only instructions, multi-perspective observations and a small piece of action history) for the purpose of controlled comparison. The key is: <strong>semantic actions are</strong> predicted using VLM’s own native vocabulary. There are no additional action heads and no special tokens, so a rank-64 LoRA (freezing the visual encoder and multi-modal projection layer, only updating about 3% of parameters) is enough. Qwen3.5-2B can be trained on a single H200 in less than 2 hours, 24GB Level graphics cards can also run.</p>\n<h4 id=\"-gumi把动作词表变成一个网页\">⑦ GUMI: Turn the action vocabulary into a web page</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-GUMI-interface.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: GUMI interface: Each semantic action unit corresponds to a button with a key. People can use the keyboard to \"play\" the robot, and the computer-use agent can also directly operate the same web page. Each arm has a set of keys and supports action queuing and submission.</a>\n<figcaption>GUMI interface: Each semantic action unit corresponds to a button with a key. People can use the keyboard to \"play\" the robot, and the computer-use agent can also directly operate the same web page. Each arm has a set of keys and supports action queuing and submission</figcaption>\n</div>\n<p>Because the action space is discrete and can be directly manipulated by humans, the author conveniently made it into a graphical interface GUMI. Each unit is mapped to a button with a shortcut key: a human can control it with a keyboard, a computer-use agent can click on the same web page, and a general-purpose VLM agent can directly predict the symbols. Each step of GUMI records the pair of “pre-execution observation + selected semantic action” \\((o_t, a_t)\\), which is naturally a trainable sample; and because the implementation of the interpreter is deterministic, the same rollout can also leave underlying instructions and tracks incidentally - <strong>A demonstration can simultaneously train the semantic action strategy and the continuous control strategy</strong>.</p>\n<p>Compared with acquisition pipelines that rely on dedicated teleoperation hardware or simulation-specific control, GUMI does not require any special hardware and supports single-step control, action queuing, single-arm, and hybrid acquisition where humans intervene to correct during agent rollout; the same batch of demonstrations can be reused between different embodiments that implement the same set of units, and also supports remote acquisition (people do not have to stay with the robot).</p>\n<hr/>\n<h3 id=\"3-核心结果发现-4\">3. Results and findings</h3>\n<p><strong>Experimental setup</strong>: Two real robots - 7-DoF Franka Research 3 (one RealSense D435 external view facing the workbench + one wrist D405) and two-arm AgileX (two 6-DoF arms, one shared self-view + one per wrist, three Orbbec Dabai DC1 in total). The task is 5 objects (squares, bananas, tennis balls, teddy bears, chess pieces) × 2 containers (plates, bowls) = 10 catch-and-place tasks, each task has 10 random placement trials, and the upper limit of a single episode is 50 steps before the timeout fails. The FT mode demo only covers cubes, bananas, and tennis balls, leaving teddy bears and chess pieces as OOD. ZS uses Gemini-3.1 Pro by default (medium thinking effort), and FT uses Qwen3.5-2B by default. The demo has a total of 164 real robot episodes (7.8K decision steps) + 230 simulation episodes (13.5K steps, from ManiSkill and RoboLab).</p>\n<p>The three levels of generalization of <strong>are significantly ahead of</strong> (success rate, average):</p>\n<table>\n<thead>\n<tr>\n<th>generalization level</th>\n<th>π0.5</th>\n<th>GR00T</th>\n<th>Harness-VLA</th>\n<th>Goal-VLA</th>\n<th>CaP-X</th>\n<th>RATS</th>\n<th><strong>ZS</strong></th>\n<th><strong>FT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cross-Task (10 tasks)</td>\n<td>39.0</td>\n<td>35.0</td>\n<td>50.0</td>\n<td>13.0</td>\n<td>44.0</td>\n<td>57.0</td>\n<td><strong>89.0</strong></td>\n<td><strong>86.0</strong></td>\n</tr>\n<tr>\n<td>Cross-Environment</td>\n<td>40.0</td>\n<td>34.0</td>\n<td>63.8</td>\n<td>15.0</td>\n<td>52.5</td>\n<td>65.0</td>\n<td><strong>100.0</strong></td>\n<td><strong>88.0</strong></td>\n</tr>\n<tr>\n<td>Cross-Embodiment</td>\n<td>41.0</td>\n<td>36.0</td>\n<td>49.0</td>\n<td>11.0</td>\n<td>43.0</td>\n<td>52.0</td>\n<td><strong>93.0</strong></td>\n<td><strong>87.0</strong></td>\n</tr>\n</tbody>\n</table>\n<p>A few points worth mentioning separately: The advantage is also true for the teddy bears and chess pieces that <strong>has not appeared in the fine-tuning data</strong> (ZS is 10/10 on the chess piece task, π0.5 is only 1/10); <strong>sim-to-real</strong> In one item, FT, which only uses simulation demonstration training, gets 13/20, while π0.5 and GR00T, which also only feed simulation data, get 0/20; when <strong>crosses embodiment</strong>, ZS only needs to change an interpreter, and FT directly evaluates each after joint training on the data of both arms.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-capability-analysis.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Capability analysis: The upper four boxes are physical adaptability (fine control, rotation extrapolation, action combination, workspace offset), and the lower three boxes are multi-arm collaboration and semantic adaptability (reasoning-intensive tasks, video in-context learning)</a>\n<figcaption> Capability analysis: The upper four boxes are physical adaptability (fine control, rotation extrapolation, action combination, workspace offset), and the lower three boxes are multi-arm collaboration and semantic adaptability (inference-intensive tasks, video in-context learning)</figcaption>\n</div>\n<p><strong>Physical adaptability - change the interpreter instead of retraining the model</strong></p>\n<ul>\n<li><strong>Fine control</strong>: Block stacking and latch tasks, only adjusting the interpreter step size from 2 cm to 1 cm, without moving the interface and not retraining, ZS increased from 60% to 80%, FT increased from 40% to 65%; π0.5 trained with the same batch of demonstrations was only 15%, and an additional batch of fine motion data was required to reach 60%.</li>\n<li><strong>action combination</strong>: Synthesizing two orthogonal translation units into one diagonal displacement is only a matter of the interpreter - ZS has −26% steps per episode, FT −24%, and the success rate has only dropped slightly from 94%/84% to 92%/82%.</li>\n<li><strong>Rotation Extrapolation</strong>: See example below.</li>\n<li><strong>workspace offset</strong>: expanded from the core 25% area (S@1) to 90% close to the boundary (S@3), ZS 98%→92%, FT 88%→82% only declined slightly, and π0.5 collapsed from 48% to 24%.</li>\n<li><strong>Multi-arm collaboration</strong>: On both AgileX arms, the joint action prediction of “clearing the table” is 90% (0 collisions), while the two independent single-arm agents each manage only 70% (1 collision); the gap in “passing bananas” that requires handover is even greater - joint 70% (0 collisions) versus independent 30% (3 collisions).</li>\n</ul>\n<blockquote>\n<p><strong>as an example (rotation extrapolation)</strong>: Each <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> only rotates 15°. In the training demonstration, the carrot only swung through 0° and 45°, but during the test it swung to an unseen 90° - the model does not need to have “seen 90°”, as long as it vomits 6 <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> in a row, it will be in place. FT gets 70% at 90°, while the π0.5 of direct regression to continuous action is only 20%: the angle of the regression output is locked by the training distribution, while the incremental unit can be extrapolated by repeated combinations. By the way, if the rotation unit is removed from the vocabulary, the success rates at 45° and 90° drop to 50% and 10% respectively.</p>\n</blockquote>\n<p><strong>Semantic adaptability—preserving VLM’s instruction following flexibility</strong></p>\n<ul>\n<li><strong>Reasoning-intensive task</strong> (find out which of the three inverted cups hides the square, arrange the scattered letters to form “SHOW”): ZS opens Situated Planning and gets 85%, FT and π0.5 run alone only 10% and 0%; feed them the same subtask instructions generated by Gemini, FT rises to 70%, π0.5 still only has 5%.</li>\n<li><strong>video in-context learning</strong>: It is required to collect three objects in the order in the demonstration video. When there is no demonstration, ZS only gets 20% (the order is not clear in the first place). After giving a human or robot demonstration video, both sources are 20/20; FT gets 90% from both sources under the condition of the task outline extracted by the same planner.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-plugin-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Ablation of nine plug-ins (real robot Franka + Gemini-3.1 Pro zero sample): the default plug-in leaves one method behind, Visual Prompt and Situated Planning are superimposed on the default configuration and evaluated in special scenarios, the complete configuration baseline is 96%</a>\n<figcaption> Ablation of nine plug-ins (real robot Franka + Gemini-3.1 Pro zero sample): The default plug-in leaves one method behind, Visual Prompt and Situated Planning are superimposed on the default configuration and evaluated in special scenarios. The complete configuration baseline is 96%</figcaption>\n</div>\n<p><strong>plug-in ablation</strong> (complete configuration 96%):</p>\n<ul>\n<li><strong>Multi-View Guidance</strong>: Drops to 58% only for global view - wrist view is almost a necessity for fine alignment of small objects.</li>\n<li><strong>Proprioception</strong>: Removed and dropped to 68%. Compact signals such as gripper height and contact status provide reliable guidance when appearance or depth makes visual judgment slip.</li>\n<li><strong>Subtask Planning</strong>: Removed and dropped to 60%. A typical failure is <strong>dragging the object toward the plate without lifting it</strong> - this problem disappears only after the operation sequence is broken into stages that are locally valid and can be verified by images.</li>\n<li><strong>Action Chunking</strong>: Turning it off is still 96% but requires 32 model calls; forcing chunk throughout the process reduces the calls to 20 times (-38%) but drops to 74%. Conclusion supports <strong>selective chunk</strong>: compresses redundant handling segments and retains fine-grained feedback before and after contact.</li>\n<li><strong>Adaptive Step</strong>: Only 82% of fine steps are used (38 steps, easy to overshoot), only 70% of coarse steps are used (22 steps, easy to overshoot), and 96% of adaptive switching is based on target visibility (30 steps).</li>\n<li><strong>Visual Prompt</strong>: Basically ineffective in regular tasks (96% vs 94%), support it to be turned off by default; but in “grasping the cup handle” it improved from 40% to 85%. Note that just drawing the mark without language alignment is 35% - <strong>The gain comes from explicitly aligning the language instructions with the marked interaction points, not the mark itself</strong>.</li>\n<li><strong>Situated Planning</strong>: Zero impact on regular tasks, hidden object search increased from 35% to 85%.</li>\n<li><strong>Action History</strong>: After removal, it dropped to 76%, and the number of steps increased from 30 to 39. Most of the failures were oscillations between opposite actions.</li>\n<li><strong>Failure Recovery</strong>: Removed and dropped to 72%. The main failure mode is undetected empty gripping, and then the empty gripper is used to continue through the rest of the process.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-action-space-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: 2×2 ablation of action space representation: the horizontal axis is whether there is an explicit agreement, and the vertical axis is semantic name or arbitrary symbol; the right side is the direction mapping confusion matrix detected by the model under setting (D), with a large area mirrored in the left and right directions</a>\n2×2 ablation of<figcaption> action space representation: the horizontal axis is whether there is a clear text agreement, the vertical axis is the semantic name or an arbitrary symbol; the right side is the direction mapping confusion matrix detected by the model under setting (D), with a large area mirrored in the left and right directions</figcaption>\n</div>\n<p><strong>The most interesting group of ablation - what exactly does the action symbol rely on grounding</strong>. The author fixed the rest of the harness unchanged and only changed the representation of the six translation units to do a 2×2 comparison:</p>\n<table>\n<thead>\n<tr>\n<th> </th>\n<th>There is an express agreement</th>\n<th>No express agreement</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>semantic name</strong> (<code class=\"language-plaintext highlighter-rouge\">MV_LEFT</code>…)</td>\n<td>(A) <strong>100%</strong>, 25 steps</td>\n<td>(B) 90%, 34 steps</td>\n</tr>\n<tr>\n<td><strong>Any symbol</strong> (A–F)</td>\n<td>(C) <strong>95%</strong>, 27 steps</td>\n<td>(D) <strong>5%</strong>, 49 steps</td>\n</tr>\n</tbody>\n</table>\n<p>The reading is: <strong>The convention provides most of the grounding, and the semantic name is just a useful prior</strong>. Any symbol is paired with a clear description of “where this symbol will move the end” (C), which is almost the same as the default configuration; conversely, only semantic names are given without conventions (B), although it can still be used, but the efficiency is significantly reduced. In setting (D), the model can only test it by itself - spitting out an unknown symbol, comparing observations before and after, and guessing its effect - only 1 episode was successful out of 20 episodes, and the inferred mapping was only 23.3% correct (randomly 16.7%), and the left and right directions on the confusion matrix mirrored each other in large areas. <strong>It is unreliable to rely solely on visual changes to deduce action semantics. Writing the agreement into prompt is the key.</strong></p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-backbone-thinking-effort.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Left: The distribution of different cutting-edge VLM and thinking effort on the success rate-number of steps plane; Right: The ability to place chess cannons is divided into two stages: planning and fine-grained alignment. The bottleneck is obviously in the latter.</a>\n<figcaption> Left: The distribution of different frontier VLM and thinking effort on the success rate-number of steps plane; Right: In the chess cannon placement task, the ability is divided into planning and fine-grained alignment. The bottleneck is obviously in the latter</figcaption>\n</div>\n<p><strong>backbone model and thinking budget</strong>: Zero-sample performance generally follows the capabilities of the underlying model (Gemini-3.1 Pro &gt; GPT-5.6-sol &gt; Opus 5 &gt; GPT-5.6-luna &gt; Gemini-3.6 Flash). To improve thinking effort, <strong>mainly reduces the number of redundant interaction steps</strong>. The improvement in success rate is limited, but the wall clock time increases significantly (GPT-5.6-sol reaches 3.4×). The command following of all models is very stable, and more than 98% of the responses can produce legal action units. Taking the chess cannon placement task apart, <strong>planning is not the bottleneck of</strong> (the plan correct of the three models are all 80–95%). The errors are concentrated in fine grasping and placement (place correct is only 70/30/15); additionally given the target bounding box, it can be mentioned further, indicating that explicit visual grounding clues are of great value.</p>\n<p><strong>Fine-tuning backbone scale</strong>: 2B is already very strong, and the larger backbone mainly has gains in fine tasks such as stacking and latching; the 1B-level model will do too many local fine-tuning near the target, resulting in a significantly longer set length; but the small model can outperform the large model in tasks such as tennis that require timely correction of moving objects. Overall 2B is a balance between accuracy and responsiveness.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-qualitative-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Qualitative results of real robot: new objects, background changes, lighting changes, cluttered scenes, spatial reasoning (putting letters to spell \"SHOW\") and double-arm coordination (opening drawers and putting cups in) are all completed by the same set of action interfaces</a>\n<figcaption> real robot qualitative results: new objects, background changes, lighting changes, cluttered scenes, spatial reasoning (putting letters to spell \"SHOW\") and arm coordination (opening drawers and placing cups) are all completed by the same set of action interfaces</figcaption>\n</div>\n<hr/>\n<h3 id=\"4-局限性-4\">4. Limitations</h3>\n<ol>\n<li><strong>embodiment has limited coverage</strong>: Currently, it has only been verified on single-arm (Franka) and double-arm (AgileX) operations equipped with parallel grippers. It is still unknown to extend it to embodiments with higher degrees of freedom and more complex contact patterns such as dexterous hands and humanoids;</li>\n<li><strong>Single sensing mode</strong>: The sensing side only has vision and embodiment states, lacks tactile and force feedback, and is still short of fine physical interactions that require intensive contact and compliant control.</li>\n</ol>\n<hr/>\n<h2 id=\"space\">6. SPACE (2026)</h2>\n<p>———Learn from programmed skills when to act continuously and when to stop and observe</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.02042\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.02042</a></p>\n<hr/>\n<h3 id=\"精华-5\">Key takeaways</h3>\n<ul>\n<li>The key to <strong>action blocks is boundaries</strong>: Outputting multiple actions at once can reduce large model calls, but the strategy also needs to learn which actions can be executed continuously, and when it should stop to obtain new observations.</li>\n<li><strong>uses skill structure to provide supervision</strong>: SPACE summarizes compound skills and sub-skills from success trajectories, converts sub-skill call boundaries into action block boundaries, and supplements the time structure that terminal rewards are difficult to provide directly.</li>\n<li><strong>has skills during training and takes direct action during deployment</strong>: Skill calls are expanded into ordinary action block samples and trained together with data independently sampled by the strategy. The final strategy does not need to access the skill library.</li>\n<li><strong>Simultaneously compares the entire trajectory with the local state</strong>: The trajectory-level advantage measures the final result, and the block-aware step-level advantage compares the returns discounted by decision round under the same anchor point observation, so that the learning signal takes into account both success and decision-making efficiency.</li>\n<li><strong>The benefits have a clear experimental scope</strong>: In the text interaction settings of ALFWorld and ScienceWorld, SPACE improves 7.0–31.3 percentage points compared with the baseline with the highest success rate in each setting, and reduces LLM decision rounds.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-5\">1. Background and problem</h3>\n<p>ReAct-style agents usually only generate one atomic action per round, read environmental feedback after execution, and then call a large model to determine the next step; deterministic routines in long-term tasks therefore require multiple model calls. Directly changing to output a variable-length action sequence at once, and then using standard reinforcement learning training may not necessarily lead to good learning: the paper observed phenomena such as single action collapse, excessively long action blocks leading to a decrease in success rate, and multi-action PPO training being unstable. The authors attribute the core difficulty to action block boundary learning—sparse terminal rewards lack supervision that directly signals “this is the time to pause and re-observe.”</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-multiaction-failure-modes.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Single-action collapse and over-commitment phenomenon of multi-action GRPO\" loading=\"lazy\" decoding=\"async</a>\n<figcaption> allows the output of multiple actions and does not guarantee effective chunking; different backbone models exhibit single-action collapse and over-commitment respectively</figcaption>\n</div>\n<hr/>\n<h3 id=\"2-主要方法创新点-5\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: SPACE skill induction, hybrid sampling, joint training and deployment process\" loading=\"lazy\" decoding=\"async</a>\n<figcaption> Successfully generated programmed skills from trajectories. Skill calls were expanded into original action blocks and trained together with directly sampled action blocks; only the action block strategy was retained during testing</figcaption>\n</div>\n<p>SPACE (Skill-guided Policy with Adaptive Chunk Execution) consists of two layers of programmed skills <strong>, hybrid trajectory sampling and skill expansion, and block-aware policy optimization</strong>. Skills provide reusable task decomposition, the expansion process converts the decomposition into training samples, and joint optimization absorbs this structure into a strategy that directly outputs action blocks.</p>\n<h4 id=\"-动作块接口减少决策次数保留必要的反馈边界\">① Action block interface: Reduce the number of decisions and retain necessary feedback boundaries</h4>\n<p>First write several actions at a time, and then execute them sequentially by the executor. This is action chunking (Action Chunking). The strategy generates $u_i=(a_{i,1},\\dots,a_{i,L_i})$ based on the interaction history $h_i$ of the $i$ round, where $1\\leq L_i\\leq K$; the executor stops execution when the block is completed or encounters an invalid action, and then enters the next LLM decision, experimental setting $K=6$.</p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>single action strategy</th>\n<th>Simple multi-action RL</th>\n<th>SPACE</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Output per round</td>\n<td>an atomic action</td>\n<td>Variable length atomic action sequence</td>\n<td>Variable length atomic action sequence</td>\n</tr>\n<tr>\n<td>How to determine boundaries</td>\n<td>Fixed segmentation after each action</td>\n<td>Mainly relies on task reward learning</td>\n<td>Demonstration of adding sub-skill boundary formation</td>\n</tr>\n<tr>\n<td>training data</td>\n<td>Atomic motion trajectory</td>\n<td>Autonomously generated action block trajectories</td>\n<td>Autonomous action blocks and skill expansion action blocks</td>\n</tr>\n<tr>\n<td>test interface</td>\n<td>single action</td>\n<td>action block</td>\n<td>Action block, no skill call</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Take an example (mechanism diagram)</strong>: If the location of the refrigerator is known, you can first output “walk to the refrigerator and open the refrigerator”, wait for feedback to confirm what objects are inside, and then decide which object to take. If objects that have not yet been confirmed to exist are also written into the same block in advance, it may fail due to lack of mid-way feedback; it is this kind of trade-off that boundary learning aims to solve.</p>\n</blockquote>\n<h4 id=\"-两层程序化技能把成功经验变成可切分的例程\">② Two levels of procedural skills: turning successful experiences into divisible routines</h4>\n<p><strong>input</strong> is the trajectory of successful interaction. The large model divides it into sub-task stages, generating a composite skill responsible for scheduling, and several sub-skills (Subskills) that complete local routines; each sub-skill contains behavior descriptions, parameter modes and executable functions, and the composite skill also records an ordered sequence of sub-skill calls. The generated code is checked for syntax, compilability and function signature, and then standardized and deduplicated according to the Abstract Syntax Tree (AST). <strong>output</strong> to the skill library.</p>\n<p>The two-layer structure provides a specific basis for segmentation: the composite skill is responsible for the sequence of “find the object first, then heat it, then place it”. Each sub-skill call corresponds to an action block, and block boundaries are formed between calls. These bounds are training demonstrations taken from the program structure and do not imply that they have been proven to be optimal bounds for all states.</p>\n<p><strong>Cold start and update</strong>: Appendix A.2 clearly uses the initial skills of manual sorting, 3 for ALFWorld and 5 for ScienceWorld, and serves as a few sample examples for subsequent skill induction. The search prioritizes the matching task category, and selects the top 3 composite skills based on the UCB-style score that combines the success rate and the number of uses; when there is no corresponding category, 7 sub-skills that are as diverse as possible are retrieved based on the description semantic similarity. During training, skills are regularly summarized from new success trajectories, with a maximum of 20 composite skills for each type, and entries with zero long-term success rate are cleared.</p>\n<h4 id=\"-混合采样与技能展开把代码调用转换为部署接口\">③ Mixed sampling and skill expansion: convert code calls into deployment interfaces</h4>\n<p>The training is based on <strong>track</strong> mixed two modes. The trajectory of proportion $\\rho_{\\mathrm{prim}}$ adopts Primitive-Chunk Mode, and the strategy directly outputs action chunks to form the same strategy data $\\mathcal D_{\\mathrm{on}}$; the remaining trajectories adopt Skill-Augmented Mode, and the strategy receives the retrieved skills and can output original action chunks or call skills.</p>\n<p>In order for the deployment strategy to output only atomic action sequences, skill enhancement trajectories are expanded via Skill-to-Chunk Expansion:</p>\n<ul>\n<li>Already the output of the original action block, leave it as is.</li>\n<li>Calling a sub-skill is converted into a set of “current history, action blocks output by this sub-skill”.</li>\n<li>Call a compound skill and expand it into multiple groups of samples along the order of its sub-skill calls; the history of the latter sample contains the feedback after the execution of the previous action block.</li>\n</ul>\n<blockquote>\n<p><strong>Take an example (only demonstrates segmentation)</strong>: A composite skill call executes 3 sub-skills in sequence, which produce 2, 3, and 2 atomic actions respectively. After expansion, three action block samples with lengths 2, 3, and 2 are obtained. Each sample is matched with the history at the corresponding boundary; these 7 actions will not be merged into one block. The policy thus learns both the action content and the block end position.</p>\n</blockquote>\n<p>These expanded samples form hetero-strategy data $\\mathcal D_{\\mathrm{off}}$. The “different strategies” here refer to samples that have been executed and rewritten by skills, rather than raw data directly collected by the deployment strategy through the same interface; they are continuously generated during the training process and do not necessarily come from a fixed pre-collected data set.</p>\n<p>The default original action block sampling ratio is 0.5 in ALFWorld and 0.75 in ScienceWorld; the 8 tracks per task in the former can be divided into 4 direct sampling and 4 skill-enhanced sampling, while the latter is 6 and 2. The two-way samples are finally aligned to the same interface, so the trained policy does not need to retrieve skills or execute skill functions.</p>\n<h4 id=\"-块感知信用分配整条轨迹与相同状态分别比较\">④ Block-aware credit allocation: compare the entire trajectory with the same state separately</h4>\n<p>To judge whether an action deserves to be learned more or less, SPACE simultaneously looks at “what is the result of the entire trajectory” and “how is the subsequent performance under the same observation”, that is, Chunk-Aware Two-Level Advantages. Let $M_\\tau$ be the number of decision rounds in the unified action block representation, $r(\\tau)$ be the terminal reward, the sampling group with the same task and initial conditions is recorded as $\\mathcal G$, and the trajectory-level advantage is:</p>\n\n\\[A_{\\tau}^{\\mathrm{traj}}=\\frac{r(\\tau)-\\mu_{\\mathcal G}}{\\sigma_{\\mathcal G}+\\epsilon}.\\]\n\n<p>For the $i$ action block, first calculate the reward of <strong>discount according to</strong> remaining decision round, and then broadcast it to each action in the block:</p>\n\n\\[G_{\\tau,i}=\\gamma_c^{M_\\tau-i}r(\\tau).\\]\n\n<p>Then take the anchor state key $z_{\\tau,i,j}$ observed before the action is executed, form a set $H(z)$ of action occurrence positions sharing the same anchor point, and normalize it by the return mean and standard deviation of the set:</p>\n\n\\[A_{\\tau,i,j}^{\\mathrm{step}}=\n\\frac{G_{\\tau,i}-\\mu_{H(z_{\\tau,i,j})}}\n{\\sigma_{H(z_{\\tau,i,j})}+\\epsilon},\n\\qquad\nA_{\\tau,i,j}=A_{\\tau}^{\\mathrm{traj}}+\\lambda_{\\mathrm{step}}A_{\\tau,i,j}^{\\mathrm{step}}.\\]\n\n<blockquote>\n<p>Take <strong>as an example (set your own value and ignore the stable term)</strong>: Two successful trajectories take one action at the same anchor point, and the terminal rewards are both 1, but then 1 and 3 rounds of decision-making are required respectively; taking $\\gamma_c=0.9$, the corresponding rewards are 0.9 and 0.729. If the anchor point group only has these two samples, calculated based on the overall standard deviation, the mean is 0.8145, the standard deviation is 0.0855, and the step advantages are +1 and −1 respectively. This local signal biases paths with fewer subsequent decisions; the raw rewards of actions within the same block are the same, but the final advantage can still be different if the anchor comparison group is different.</p>\n</blockquote>\n<p>This is a method of assigning credit based on relative returns within a group, and one cannot claim that it accurately identifies the causal contribution of each action. The problem statement in the article uses success/failure terminal rewards, while the actual training in ScienceWorld uses scaled task scores according to Appendix A.2, and cuts negative values ​​to 0. Abstract settings and specific implementations should be distinguished.</p>\n<h4 id=\"-联合训练目标与推理流程\">⑤ Joint training goals and inference process</h4>\n<p>The original action block trajectory uses PPO-style clipping targets. Let $p_\\theta(a_{\\tau,i,j})$ abbreviated strategy generate the probability of this action under the conditions of history $h_i$ and previous actions in the block, $q_{\\tau,i,j}=p_\\theta(a_{\\tau,i,j})/p_{\\mathrm{old}}(a_{\\tau,i,j})$ is the probability ratio of the old and new strategies, then:</p>\n\n\\[\\mathcal L_{\\mathrm{on}}=-\\mathbb E_{\\tau\\sim\\mathcal D_{\\mathrm{on}}}\n\\left[\\sum_{i=1}^{M_\\tau}\\sum_{j=1}^{\\ell_i}\n\\min\\left(q_{\\tau,i,j}A_{\\tau,i,j},\n\\operatorname{clip}(q_{\\tau,i,j},1-\\varepsilon,1+\\varepsilon)A_{\\tau,i,j}\\right)\\right].\\]\n\n<p>This term increases the probability of favorable actions while limiting the scope of strategy updates; consistent with the original presentation, the KL regular term is omitted here. The skill expansion data uses advantage-weighted self-imitation targets:</p>\n\n\\[\\mathcal L_{\\mathrm{off}}=-\\mathbb E_{\\tau\\sim\\mathcal D_{\\mathrm{off}}}\n\\left[\\sum_{i=1}^{M_\\tau}\\sum_{j=1}^{\\ell_i}\nw(A_{\\tau,i,j})\\log p_\\theta(a_{\\tau,i,j})\\right],\n\\qquad w(A)=\\operatorname{clip}(A,0,w_{\\max}).\\]\n\n<p>This item retains the imitation weights of positive dominant samples and limits excessive weights, distilling the action blocks and their boundaries obtained by skill expansion into the strategy. The overall goal is:</p>\n\n\\[\\mathcal L(\\theta)=\\mathcal L_{\\mathrm{on}}(\\theta)+\\lambda_{\\mathrm{off}}\\mathcal L_{\\mathrm{off}}(\\theta).\\]\n\n<p>When implemented, the advantage of each atomic action is broadcast to the output token corresponding to that action. By default, 16 tasks are sampled per training step, 8 trajectories per task, the learning rate is $10^{-6}$, the history length is 5, and both backbone models run in no-thinking mode.</p>\n<p>The end-to-end process is: hybrid sampling → unfold skill trajectories → calculate two-level advantages → joint update strategy → regularly update the skill library from successful trajectories. During testing, the loop is directly in the manner of “interaction history → variable-length action block → sequential execution → new feedback”. LLM is not re-invoked in the middle of the block; the skill library and its retrieval and execution components no longer participate in reasoning.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-5\">3. Results and findings</h3>\n<p><strong>Main results (Table 1, Table 2)</strong> : SR is the success rate, and round is the average number of LLM decisions per episode. Select each setting uniformly in the table below <strong>Baseline with the highest success rate</strong> Compare and avoid piecing together the success rates of different baselines with the lowest rounds.</p>\n<table>\n<thead>\n<tr>\n<th>Environment / Backbone / Partition</th>\n<th>compare baseline</th>\n<th>Baseline SR → SPACE SR</th>\n<th>Gain (percentage points)</th>\n<th>Baseline round → SPACE round</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ALFWorld / Qwen3-4B / Seen</td>\n<td>GiGPO (SR alongside Multi-action GRPO)</td>\n<td>85.2% → 99.2%</td>\n<td>+14.0</td>\n<td>15.9 → 3.7</td>\n</tr>\n<tr>\n<td>ALFWorld / Qwen3-4B / Unseen</td>\n<td>Multi-action GRPO</td>\n<td>81.3% → 96.9%</td>\n<td>+15.6</td>\n<td>20.9 → 4.4</td>\n</tr>\n<tr>\n<td>ALFWorld / Llama-3.1-8B-Instruct / Seen</td>\n<td>GiGPO</td>\n<td>89.1% → 96.1%</td>\n<td>+7.0</td>\n<td>14.5 → 5.0</td>\n</tr>\n<tr>\n<td>ALFWorld / Llama-3.1-8B-Instruct / Unseen</td>\n<td>GiGPO</td>\n<td>83.6% → 94.5%</td>\n<td>+10.9</td>\n<td>18.8 → 5.2</td>\n</tr>\n<tr>\n<td>ScienceWorld / Llama-3.1-8B-Instruct / Seen</td>\n<td>GiGPO</td>\n<td>35.9% → 67.2%</td>\n<td>+31.3</td>\n<td>10.2 → 5.2</td>\n</tr>\n<tr>\n<td>ScienceWorld / Llama-3.1-8B-Instruct / Unseen</td>\n<td>GiGPO</td>\n<td>34.4% → 61.7%</td>\n<td>+27.3</td>\n<td>10.1 → 5.8</td>\n</tr>\n</tbody>\n</table>\n<p>For example, Qwen3-4B’s ALFWorld Unseen decision rounds are reduced by approximately <strong>78.9%</strong>. In comparison, Llama’s Multi-action GRPO itself only requires 5.4/5.5 rounds, and SPACE is 5.0/5.2 rounds. The main advantage is that the success rate is increased from 71.1%/65.6% to 96.1%/94.5%; it cannot be generalized to all multi-action baselines as a 70% reduction in rounds.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-training-dynamics.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Training curves of SPACE and multi-action reinforcement learning baselines\" loading=\"lazy\" decoding=\"async</a>\n<figcaption>Qwen3-4B’s ALFWorld Unseen success rate curve, the number of actions per round of the two backbones, and the change in strategy entropy; in the later stages of SPACE, 3–4 actions per round were roughly maintained</figcaption>\n</div>\n<p><strong>Action Block Behavior</strong>: Qwen3-4B’s Multi-action GRPO is close to one action per round, and Llama-3.1-8B-Instruct tends to about 5–6 actions per round but with a lower success rate. SPACE resulted in an intermediate granularity of about 3–4 actions in these experiments while maintaining a higher success rate; this range is an experimental observation and cannot be relied upon as a universal optimal block length.</p>\n<p><strong>component ablation (Table 3, ALFWorld/Llama-3.1-8B-Instruct)</strong>:</p>\n<table>\n<thead>\n<tr>\n<th>training configuration</th>\n<th>Seen SR / round</th>\n<th>Unseen SR / round</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Complete SPACE</td>\n<td>96.1% / 5.0</td>\n<td>94.5% / 5.2</td>\n</tr>\n<tr>\n<td>Remove skills</td>\n<td>86.7% / 5.8</td>\n<td>88.3% / 5.7</td>\n</tr>\n<tr>\n<td>Remove block-aware advantages</td>\n<td>90.6% / 5.6</td>\n<td>89.1% / 7.0</td>\n</tr>\n</tbody>\n</table>\n<p>Removing either component reduces the success rate and increases the number of decision rounds, supporting the complementary role of skill-bound supervision and block-aware optimization.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-rollout-efficiency.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The impact of the total amount of training sampling decisions and the sampling ratio of the original action block\" loading=\"lazy\" decoding=\"async</a>\n<figcaption> The left picture counts ALFWorld’s training sampling LLM rounds, not the number of tokens; the right picture compares ScienceWorld’s original action block sampling ratio, the decision round of 0.75 is the lowest, and the success rate of 0.875 is higher</figcaption>\n</div>\n<p><strong>efficiency indicators need to differentiate between calibers</strong>: In Figure 3(a), SPACE reaches the final performance of Multi-action GRPO at the 40th training step, corresponding to about 26.6% of the training steps stated in the paper overview; Figure 4(a) counts <strong>sampling LLM in another backbone setting In round</strong>, it takes 43.60K times for SPACE to achieve GRPO performance, and the entire GRPO process is 564.54K times, which is about 7.72% (a reduction of 92.28%). The entire SPACE process is 104.46K times; these values ​​cannot be directly regarded as total tokens, GPU time or end-to-end training costs.</p>\n<p>Trade-off of <strong>sampling ratio</strong>: In Figure 4(b), $\\rho_{\\mathrm{prim}}=0.75$ corresponds to a success rate of 64.5% and 5.51 rounds; 0.875 corresponds to 66.4% and 6.84 rounds. The author chose 0.75 as a compromise between success rate and efficiency. However, the statement in the text that “the success rate is also higher” is inconsistent with the value in the figure. Here, the illustration is based on the data shown in the figure.</p>\n<p><strong>Search during test (Table 4)</strong>: On the difficult validation subset of ScienceWorld, the Best-of-N search takes $N=8$, the GRPO success rate increases from 33.3% to 37.5% (+4.2 percentage points), and SPACE increases from 52.1% to 60.4% (+8.3 percentage points); the average LLM calls after adding search were 74.9 and 48.3 respectively. Single action candidates use 3-step environment look-ahead scoring, and action block candidates use complete block execution scoring. Therefore, this result depends on the evaluation conditions that enable candidate environment look-ahead, and it does not mean that the two environment simulation costs are the same.</p>\n<hr/>\n<h3 id=\"4-局限性-5\">4. Limitations</h3>\n<ol>\n<li><strong>is only verified in the text interactive environment</strong>: The experiment only covers the text settings of ALFWorld and ScienceWorld. ScienceWorld also excludes tasks with optimal solutions exceeding 100 environmental steps. Visual input, continuous control and real robots scenarios have not been verified;</li>\n<li><strong>relies on manual cold start skills and skill induction process</strong>: The method requires manual cold start skills, and continues to summarize and execute skills during training; the main efficiency indicator of the paper is the LLM decision round, and the end-to-end training acceleration including these additional processes cannot be directly inferred based on this.</li>\n</ol>\n<hr/>\n<h2 id=\"abot-agentos\">7. ABot-AgentOS (2026)</h2>\n<p>——Universal robot Agent operating system and lifelong multi-modal memory system for embodied intelligence</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2607.10350\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2607.10350</a> · <a href=\"https://amap-cvlab.github.io/ABot-AgentOS\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-6\">Key takeaways</h3>\n<ol>\n<li><strong>Modular layered decoupling architecture</strong>: ABot-AgentOS is deployed between the underlying robot controller and the high-level basic VLM/VLA model, decoupling high-level semantic reasoning, skill execution, multi-level verification and memory retrieval, solving the problems of lack of explicit termination signals and process drift in traditional single-model controllers.</li>\n<li><strong>Agent Harness control closed-loop</strong>: Propose a “reasoning-execution-verification” closed-loop that includes global Main LLM planning, Skill Runner context-isolated local execution, and Verifier run-time/skill-time/end-time multi-stage verification, which significantly reduces false completion and blind stagnation in long-term tasks.</li>\n<li><strong>Universal Multi-modal Graph Memory</strong>: Converts speech, image observation, spatial location, time association and task trajectory into strongly typed multi-modal graph nodes and edges, supporting retrieval and local subgraph extraction based on evidence traceability.</li>\n<li><strong>Failure-Driven Lifelong Self-Evolution (Failure-Driven Lifelong Self-Evolution)</strong>: Build a fail-to-JSON DSL asset mechanism based on Trace diagnosis, adopt strict post-check gating, and achieve cumulative self-evolution with zero ground-truth leakage in cross-Split deployment.</li>\n<li><strong>Embodied WorldBench</strong>: Launches the first executable evaluation benchmark across indoor and outdoor composite scenes, covering 16 scenes, 4 difficulty levels and 200+ composite tasks; and provides an end-to-end student policy distillation training pipeline based on text sandbox and self-evolution reward engine.</li>\n</ol>\n<hr/>\n<h3 id=\"1-研究背景问题-6\">1. Background and problem</h3>\n<p>Embodied AI (Embodied AI) is pushing artificial intelligence from the digital world to the physical world. In recent years, the visual language model (VLM) and the visual language action (VLA) model have given robots excellent natural language understanding, visual scene perception and action prediction capabilities. However, a critical gap remains between semantic understanding and reliable physical execution:</p>\n<ol>\n<li><strong>Semantic beliefs are disconnected from environmental facts</strong>: In complex long-term tasks, existing end-to-end controllers or simple API calls lack explicit intermediate state verification and termination signals. The robot may have executed the navigation instructions but not moved, or it may have continuously collided locally but thought the task was progressing normally at the language level.</li>\n<li><strong>lacks cross-modality universal Agent hardware abstraction</strong>: Existing systems are mostly highly bound to specific robot forms or control interfaces, and are difficult to seamlessly extend to diverse hardware such as humanoid robots and four-legged dogs.</li>\n<li><strong>Memory is difficult to persist and trace back to self-improvement</strong>: There is a lack of a general multi-modal memory system that can be persistently stored across sessions, traceable to origin, and self-improved from historical interaction failures.</li>\n</ol>\n<p>To this end, the paper proposes <strong>ABot-AgentOS</strong>, a universal robot Agent operating system that runs on the underlying controller and decouples high-level cognition and physical actions.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-6\">2. Methods and innovations</h3>\n<p>ABot-AgentOS is scheduled by <strong>edge cloud in collaboration with dual LLM cores</strong> and <strong>Agent Harness closed-loop</strong>, <strong>general multi-modal graph memory</strong> and <strong>end-to-end distillation training pipeline</strong> are composed of four modules.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-system-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: ABot-AgentOS overall system architecture: multi-source multi-modal input through edge cloud collaboration dual LLM core routing, Agent Harness closed-loop scheduling skills and multi-level verification, combined with universal multi-modal graph memory and underlying controller</a>\n<figcaption>ABot-AgentOS overall system architecture: multi-source multi-modal input through edge cloud collaboration dual LLM core routing, Agent Harness closed-loop scheduling skills and multi-level verification, combined with universal multi-modal graph memory and underlying controller</figcaption>\n</div>\n<h4 id=\"-整体框架与边云协同双核心\">① Overall framework and edge cloud collaboration dual core</h4>\n<p>ABot-AgentOS distinguishes between edge lightweight model and cloud large model (Dual-LLM Core) in architectural design:</p>\n<ul>\n<li><strong>Edge Tiny LLM</strong>: Deployed on the robot end side, it prioritizes regular conversations, simple tool calls and real-time control instructions to reduce response delays.</li>\n<li><strong>Cloud Large LLM</strong>: When the task involves long-term complex reasoning, multi-step planning or difficult graph memory retrieval, the learned routing strategy is automatically upgraded to cloud large model processing.</li>\n</ul>\n<h4 id=\"-agent-harness-闭环控制\">② Agent Harness closed-loop control</h4>\n<p>Agent Harness changes the design of traditional single-model controllers and divides Agent scheduling into three clearly decoupled roles:</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-agent-harness.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Agent Harness Architecture details: Main LLM is responsible for global scene awareness planning, Skill Runner isolates local execution details, and Verifier provides multi-stage real-time and final verification</a>\n<figcaption>Agent Harness Architecture details: Main LLM is responsible for global scene awareness planning, Skill Runner isolates local execution details, and Verifier provides multi-stage real-time and final verification</figcaption>\n</div>\n<ol>\n<li><strong>Main LLM (Semantic Planner)</strong>: Receives user instructions and memory context, and generates adjustable high-level plans and explicit completion conditions based on the current scenario. Instead of directly emitting micro-actions for each foot, the Main LLM decides to call tools directly or delegate subtasks to a Skill Runner.</li>\n<li><strong>Skill Runner (process executor)</strong>: Runs in an independent local context as a skill-level Subagent. It handles complex processes such as local repeated movements, perspective fine-tuning, and collision recovery, and only returns compressed high-level execution result summaries to the Main LLM to prevent local details from blocking the Main LLM’s global planning.</li>\n<li><strong>Verifier (multi-stage verifier)</strong>:\n    <ul>\n<li><strong>Runtime Verification (Runtime Verification)</strong>: Monitor the trajectory and skill status, and promptly identify stagnation, local infinite loops and frequent collisions.</li>\n<li><strong>Skill Verification</strong>: Verify whether the subtask actually achieves the semantic goal, rather than just relying on Tool to return success.</li>\n<li><strong>Finish Verification</strong>: When Main LLM attempts to terminate the task, compare the initial instructions, final visual observation and environmental facts to prevent false completion.</li>\n</ul>\n</li>\n</ol>\n<h4 id=\"-通用多模态图记忆与终身自进化\">③ Universal multi-modal graph memory and lifelong self-evolution</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-memory-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Universal multi-modal memory architecture and offline fault-driven self-evolution loop: write source-traceable type graphs online, and compile failed Traces into controllable JSON DSL evolution assets offline</a>\n<figcaption> Universal multi-modal memory architecture and offline fault-driven self-evolution loop: write source-traceable type graphs online, and compile failed Traces into controllable JSON DSL evolution assets offline</figcaption>\n</div>\n<ol>\n<li><strong>Multimodal Memory Graph (Memory Graph)</strong>: Write entities, events, locations, visual frames, time associations and attribution chains (Provenance) in online interactions into strongly typed nodes and edges, replacing the stack of original video streams or plain text logs.</li>\n<li><strong>Hybrid Graph Retriever</strong>: combines semantic embedding, lexical matching, metadata filtering and graph edge topology expansion to extract high-quality local evidence subgraphs.</li>\n<li><strong>Failure-Driven Lifelong Self-Evolution (Failure-Driven Lifelong Self-Evolution)</strong>:\n    <ul>\n<li><strong>Split isolation protocol</strong>: In the sequence split deployment, the \\(t\\) split can only use the evolution asset \\(A_{&lt;t}\\) that has been promoted in history.</li>\n<li><strong>Trace diagnosis and asset compilation</strong>: After the split is completed, the system performs Trace diagnosis on the failed sample and generates candidate evolution assets in JSON DSL format (covering the stages of memory writing, evidence selection, frame selection, time normalization, etc.).</li>\n<li><strong>Strict gating verification (Gating)</strong>: The candidate asset must improve the score on the target verification set and not reduce the performance on the regression set:\n\\(\\text{Accept}(a) = \\mathbb{I}[\\Delta S_{\\text{target}}(a) \\ge \\tau_{\\text{gain}} \\land \\Delta S_{\\text{reg}}(a) \\ge -\\tau_{\\text{reg}}]\\)\nAfter passing the inspection, it can be upgraded to \\(A_{\\le t}\\) for subsequent split use, achieving cumulative growth without label leakage.</li>\n</ul>\n</li>\n<li><strong>Edge-cloud collaborative privacy management</strong>: Private memories (faces, personal items, etc.) are retained at the edge, and only public environmental memories (roadblocks, road landmarks) without sensitive information are shared on the cloud, with a privacy classification accuracy of over 99%.</li>\n</ol>\n<h4 id=\"-embodiedworldbench-与策略蒸馏训练管线\">④ EmbodiedWorldBench and policy distillation training pipeline</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-embodied-world-bench.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: EmbodiedWorldBench evaluation benchmark overview: 16 executable scenarios and 4-level difficulty settings covering indoor and outdoor composite scenes, NPC interactions and dynamic events</a>\n<figcaption>EmbodiedWorldBench evaluation benchmark overview: 16 executable scenarios and 4-level difficulty settings covering indoor and outdoor composite scenes, NPC interactions and dynamic events</figcaption>\n</div>\n<p>The paper launched <strong>EmbodiedWorldBench</strong>, covering 16 indoor, outdoor and mixed scenes, with 4 difficulty levels and 200+ composite tasks involving navigation, NPC interaction, item search and dynamic event response.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-training-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Student policy end-to-end training pipeline: build environment through text sandbox, self-evolution reward engine to generate preference data and use DPO/SFT to optimize edge deployment model</a>\n<figcaption> Student policy end-to-end training pipeline: build environment through text sandbox, self-evolution reward engine to generate preference data and use DPO/SFT to optimize edge deployment model</figcaption>\n</div>\n<p>In order to transfer the capabilities of the large cloud model Agent Harness to the small on-device model, the paper designed an end-to-end distillation pipeline:</p>\n<ol>\n<li><strong>Controllable text sandbox construction</strong>: Use LLM to automatically generate a text sandbox environment with executable status and complex logic.</li>\n<li><strong>self-evolution reward engine</strong>: Generate automatic scoring and DPO preference pairs based on structured Trace.</li>\n<li><strong>SFT + DPO policy optimization</strong>: Training and deploying lightweight Student Policy in a sandbox environment.</li>\n</ol>\n<hr/>\n<h3 id=\"3-核心结果发现-6\">3. Results and findings</h3>\n<ol>\n<li><strong>Long-range embodied execution</strong>: In the initial subset evaluation of EmbodiedWorldBench, ABot-AgentOS achieved significant improvements in task success rate (Success Rate) and goal completion (Goal Completion) compared with the single controller baseline, and the Verifier mechanism reduced early false terminations by more than 35%.</li>\n<li><strong>multi-modal memory benchmark is fully ahead of</strong>:\n    <ul>\n<li><strong>LoCoMo</strong> (long-horizon session memory): Static version reaches <strong>87.5</strong>, +Self-evo improves to <strong>88.7</strong> (close to the human upper limit of 87.7).</li>\n<li><strong>OpenEQA (EM-EQA)</strong>: Static reaches <strong>59.9</strong> under 8 frame budget, +Self-evo improves to <strong>60.4</strong> (surpassing SnapMem 57.2 and GaussExplorer 57.8).</li>\n<li><strong>Mem-Gallery</strong>: Static reaches <strong>88.6</strong>, +Self-evo improves to <strong>89.0</strong> (on conflict detection CD 97.5% with reject answer AR 100% outstanding performance).</li>\n<li><strong>NExT-QA</strong>: Validation Acc@All reaches <strong>76.5%</strong> (+Self-evo increased by 4.1 points), significantly ahead of classic video agents such as VideoAgent.</li>\n<li><strong>EgoLifeQA</strong>: Obtained the average accuracy of <strong>66.2%</strong> under single frame retrieval settings.</li>\n</ul>\n</li>\n<li><strong>Cross-task generalization of lifelong self-evolution</strong>: The self-evolution mechanism brings stable increments on all 5 memory benchmarks, and the performance gain comes entirely from general improvements to the memory pipeline (such as time normalization, relationship disambiguation), rather than indiscriminate accumulation of memory content.</li>\n</ol>\n<hr/>\n<h3 id=\"4-局限性-6\">4. Limitations</h3>\n<ol>\n<li><strong>Perception and control of noise in the complex real physical world</strong>: At present, large-scale verification is mostly carried out in executable simulation or semi-physical sandbox. In the face of high-noise depth perception, grasping failure and network communication delay in the real world, more in-depth hardware real robot tuning is still needed.</li>\n<li><strong>Automated distillation relies on text sandbox</strong>: Small model strategy distillation currently mainly relies on the text state sandbox environment. In the future, multi-modal visual observation and more complex physical simulation platforms (such as Isaac Sim/Habitat) need to be introduced.</li>\n<li><strong>Memory self-evolution requires a credible feedback signal</strong>: The offline self-evolution mechanism relies on deterministic error diagnosis or human feedback. How to safely define “answer errors” in an open unsupervised environment is still a long-term challenge.</li>\n</ol>\n<hr/>\n<h2 id=\"harness-robotic-os\">8. Harness Robotic OS (2026)</h2>\n<p>——Upgrade the four-legged inspection from “navigation stack” to “embodied agent runtime”</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.11225\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.11225</a></p>\n<hr/>\n<h3 id=\"精华-7\">Key takeaways</h3>\n<p>The real question of this article is not “how to navigate more accurately”, but “how to make a bunch of ready-made modules collaborate, leave traces, and be rollable in the same context” - taking system integration itself as the research object. The most worthy reference is the hard boundary it establishes: the real-time control loop (SLAM/planning/control) and the cognitive loop (agent orchestration/memory/reflection) belong to two layers. The agent can only “orchestrate skills” but cannot directly issue movement instructions, so if the reasoning goes wrong, the motor will not be burned. The memory is divided into three layers: working / episodic / semantic based on “retention period” rather than “data type”. The retrieval is jointly conditioned by task intention, spatial location, and scene semantics to avoid stuffing the entire operation and maintenance history into each reasoning context. Self-evolution is deliberately made into “offline candidate → safety gate → staged rollout → rollback” instead of changing the model online. This is a prerequisite for long-running robots to be audited. But be clear: Cognitive runtime (speech/memory/self-evolution) in this article only has protocols and no numbers. What really outperforms the actual test is the classic navigation plus VLM inspection pipeline.</p>\n<hr/>\n<h3 id=\"1-研究背景问题-7\">1. Background and problem</h3>\n<p>Residential property inspections must cover a wide range of public spaces such as roads, fire escapes, building entrances and exits, equipment rooms, and garbage rooms. Manual patrols are limited by manpower and personal experience in terms of frequency, consistency, and traceability. Quadruped robots can climb hills and climb narrow roads, making them a suitable carrier. However, “being able to walk” does not mean “being able to perform inspections” - it also requires continuous positioning, global task planning, reactive obstacle avoidance, scene-level understanding of hidden dangers, human-computer interaction, and connection with the work order system.</p>\n<p>The author points out that a common problem in current deployed systems is that these capabilities are made into a bunch of loosely coupled modules: sensor drivers, navigation algorithms, visual language services, operating interfaces, and enterprise applications each hold state and rely on point-to-point adapters to communicate, resulting in three gaps - <strong>Semantic task intent and robot pose/observation/ Execution status is out of line</strong>, <strong>Historical task experience is not systematically retained and retrieved</strong>, <strong>Prompt words/tool strategies/task maps/skill changes are difficult to evaluate, trace and safely roll back</strong>.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-7\">2. Methods and innovations</h3>\n<h4 id=\"21-整体框架四个平面--一条自进化环\">2.1 Overall framework: four planes + a self-evolution ring</h4>\n<p>HROS divides the system into four layers: <strong>Robot Runtime</strong> (Hardware abstraction: edge computing, multi-modal sensing, connectivity and I/O, quadruped execution), <strong>Embodied Autonomy Skills</strong> (Encapsulate SLAM, perception, global planning, and local motion into stateful, reusable “skills”), <strong>Cognitive Agent Runtime</strong> (Agent orchestration, hierarchical memory, multimodal reasoning, skill and tool scheduling, and self-evolution closed-loop), <strong>Interaction and Operations</strong> (Voice and multi-modal I/O, inspection task console, enterprise closed-loop). The four layers are not call stacks but binding relationships: each skill reports its own input timestamp, execution status, confidence or failure code, and output reference to the shared context bus, and the cognitive layer monitors the progress accordingly. <strong>but does not enter the real-time control loop</strong> .</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: HROS four-layer architecture. The dark solid line is the runtime data flow, the bidirectional arrow is the binding between the agent and the skill, the dotted line is the self-evolution path, and the green line is the safety gate - only the candidate version that has passed the safety gate can return to the skill runtime</a>\n<figcaption>HROS four-layer architecture. The dark solid line is the runtime data flow, the bidirectional arrow is the binding between the agent and the skill, the dotted line is the self-evolution path, and the green line is the safety gate - only the candidate version that has passed the safety gate can return to the skill runtime</figcaption>\n</div>\n<p><strong>stuck point dimensionality reduction｜What exactly does “embodied agent runtime” have more than ordinary navigation stack</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>Regular four-legged inspection system</th>\n<th>HROS</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Status ownership</td>\n<td>Each module maintains its own state and relies on task-specific adapters to communicate point-to-point.</td>\n<td>Shared context bus, physical state and agent reasoning have the same origin</td>\n</tr>\n<tr>\n<td>historical experience</td>\n<td>Throw it away after running, leaving at most one log</td>\n<td>working / episodic / semantic third-level memory, retrieval based on intention plus location conditions</td>\n</tr>\n<tr>\n<td>Change governance</td>\n<td>Change the prompt or skill and go online directly. If something goes wrong, rely on human resources to roll it back.</td>\n<td>Candidate version goes offline and returns with security gate and staged rollout, which can be traced and rolled back</td>\n</tr>\n<tr>\n<td>control boundary</td>\n<td>The upper layer can directly issue motion instructions</td>\n<td>Agents can only use orchestration skills, and movement instructions must pass the robot-runtime interface.</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"22-robot-runtimevbot-四足平台\">2.2 Robot Runtime: Vbot quadruped platform</h4>\n<p>The physical layer uses Vbot quadrupeds as the carrier of sensing, computing power, communication and mobility: binocular cameras, 16-line lidar, IMU, GNSS and 4G/5G. The edge computer is Horizon RDK S100P (6-core ARM Cortex-A78AE + 128 TOPS Nash BPU), which runs perception and intelligent agent services on the machine. The robot controller exposes motion instructions and status feedback through the robot-runtime interface of HROS - <strong>. The design motivation of this layer of isolation is to prevent the upper-layer agent from bypassing the verification and directly sending the bottom-layer executor instruction</strong>.</p>\n<h4 id=\"23-embodied-autonomy-skills四个有状态技能\">2.3 Embodied Autonomy Skills: Four stateful skills</h4>\n<p>This layer is the only part of the entire text that has actual measured numbers. The four modules are all engineered combinations of off-the-shelf open source software:</p>\n<ul>\n<li><strong>state estimation · Fast-LIO2</strong>: Input lidar point cloud and IMU, tightly coupled to estimate 6-DoF pose and incremental mapping, and output a priori point cloud map and online pose. Three working modes - mapping (on-site survey phase), online positioning (daily patrol, real-time scanning and registration to a priori map), and relocation (tracking degradation or restoring pose after restart). The design motivation is a <strong>shared map coordinate system</strong>: residential patrols will repeatedly revisit the same asset under different lighting and different scene appearances. Only by tying each image, each waypoint, each hidden danger event, and each report to this coordinate system can HROS perform spatially related memory retrieval and cross-task comparison.</li>\n<li><strong>Local Perception · Hobot-Stereo</strong>: Inputs synchronized binocular images, outputs dense near-field depth and fuses it with lidar obstacle representation. The design motivation is that laser sparse sampling cannot adequately express short obstacles, fine structures, and occlusion boundaries in the near field. The depth points are first transformed into the map system, filtered by distance and confidence, and then inserted into the local voxel representation consumed by EGO-Planner; <strong>binocular is a supplement rather than a replacement for</strong>. Uncertain observations are treated conservatively and are deleted from the local map if they have not been observed repeatedly for a long time.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-environment-representation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Two sets of complementary environment representations. Left: Global three-dimensional point cloud map built by Fast-LIO2 in the shared mission coordinate system, used for relocation and mission planning; Right: Hobot-Stereo's dense depth (upper left), fused point cloud (upper right), RGB input (lower left), local bird's-eye geometry (lower right), filling the laser gap in the near field</a>\n<figcaption> Two sets of complementary environment representations. Left: Global three-dimensional point cloud map built by Fast-LIO2 in the shared mission coordinate system, used for relocation and mission planning; Right: Hobot-Stereo's dense depth (upper left), fused point cloud (upper right), RGB input (lower left), local bird's-eye geometry (lower right), filling the laser gap in the near field</figcaption>\n</div>\n<ul>\n<li><strong>Task Planning · PCT-Planner</strong>: Property inspection is a <strong>coverage task</strong> rather than a single query from the starting point to the end point. The route must connect the strategically defined viewpoints (firefighting facilities, equipment room entrances, garbage collection points) and be passable throughout. PCT-Planner calculates collision-free sections on the three-dimensional prior point cloud map. The task layer is sorted according to the inspection strategy and saves the results as a reusable task template. The global route at runtime is just <strong>reference</strong> instead of direct motion instructions. The progress is represented by “current road segment + current waypoint + completed viewpoint + remaining inspection actions” - in this way, the orchestrator can pause, resume, and reschedule non-safety-critical tasks without touching the local controller at all.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-inspection-route.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: PCT-Planner generates a global inspection route on a priori point cloud map, connects 8 inspection waypoints, and archives and reuses it as a task template</a>\n<figcaption>PCT-Planner generates a global inspection route on a priori point cloud map, connects 8 inspection waypoints, and archives and reuses it as a task template</figcaption>\n</div>\n<ul>\n<li><strong>Motion Intelligence · EGO-Planner</strong>: Input the global reference route, current pose, and fused obstacle representation, output a dynamically feasible local trajectory, and then convert it into quadruped control instructions constrained by speed, clearance, and continuity. Three behaviors - nominal tracking, local re-planning (generating short detours when temporary obstructions such as pedestrians, illegally parked vehicles, cleaning equipment, etc.), recovery (stopping when there is no feasible local trajectory and reporting a failure code <strong>with type</strong>, leaving it to the task layer to decide whether to wait, retry or call the operator).</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-local-corridor.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: EGO-Planner optimizes the partially passable corridor (blue area) in front of the dog walking pedestrian. The global route only gives direction, and the decision to give way is completed by the local planner</a>\n<figcaption>EGO-Planner optimizes the partially passable corridor (blue area) in front of the dog walking pedestrian. The global route only gives direction, and the decision to give way is completed by the local planner</figcaption>\n</div>\n<h4 id=\"24-cognitive-agent-runtime一接地的语音交互\">2.4 Cognitive Agent Runtime (1): Grounded Voice Interaction</h4>\n<p>Streaming ASR converts speech into a time-stamped intent hypothesis, <strong>, but does not directly execute</strong> - it must first be grounded with the current robot pose, active tasks, visible scenes, and permission policies. Ambiguous or security-related instructions must be explicitly confirmed. TTS reports task acceptance, navigation progress, discovered hidden dangers, recovery actions, and completion status. The design motivation is to allow text, voice, images, and enterprise messages to enter the same multi-modal task interface, rather than being scattered in independent applications.</p>\n<h4 id=\"25-cognitive-agent-runtime二分层记忆\">2.5 Cognitive Agent Runtime (2): Hierarchical memory</h4>\n<p>The memory is divided into three layers according to the <strong>retention period</strong>: working stores short-range information (current tasks, recent conversations, robot status, local observations, tool calls to be returned); episodic stores task fragments indexed by time (trajectories, decisions, observations, hidden danger events, failure and recovery results); semantic stores stable site knowledge (map partitions, asset identification, inspection rules, historical defects, property disposal processes). Retrieval is jointly conditioned by task intention, spatial location, scene semantics, and execution status.</p>\n<p><strong>stuck point dimensionality reduction｜What are installed in each of the three layers and how does the retrieval occur?</strong></p>\n<blockquote>\n<p><strong>Take</strong> as an example: The robot inspected the door of the power distribution room in Building 3 for the seventh time, and there was a cardboard box on the ground in the screen.</p>\n<ul>\n<li><strong>working memory</strong> Install “at this moment”: the current task ID, the sentence just now “Go to Building 3 and have a look”, the current pose, the last two frames of observation, and the Qwen3-VL call that has not yet been returned. Cleared when the task is over.</li>\n<li><strong>episodic memory</strong> “Which time” was installed: The third inspection was judged as “stuff pile” at the same location, and manual review was changed to “temporary express delivery”; the fifth time a partial replanning was triggered due to pedestrians blocking the road. Timestamped, indexed.</li>\n<li><strong>semantic memory</strong> Installation “This place has always been like this”: The power distribution room is a key fire protection area. The rule is that no objects should be piled within 1 meter in front of the door. It is a high-frequency point in the historical defect record. Does not change with a single task.</li>\n</ul>\n<p>The retrieval is not to pour all three layers into the context, but to use “intent = inspection + location = distribution room + scene semantics = there are boxes on the ground” to conditional recall: semantic gives the applicable rules, episodic gives “the last time this kind of box was judged as express delivery”, and working gives the current screen. So this time there is a chance to stop false positives - and this is what the paper says to use Recall@5 and task completion rate to measure, but the <strong>number has not yet been given to</strong>.</p>\n</blockquote>\n<h4 id=\"26-cognitive-agent-runtime三安全门把守的自进化\">2.6 Cognitive Agent Runtime (3): Self-evolution of security gate guarding</h4>\n<p>Self-evolution is clearly defined as “experience to update” <strong>Governed process</strong> , instead of changing the model online. At the end of each task, the execution trace and manual feedback are written into the experience buffer; in the reflection and evaluation phase, success or failure scoring, failure attribution, consistency checks are performed, and candidate updates (memory entries, prompts, tool selection strategies, task diagrams, reusable skills) are produced; candidate versions are evaluated on offline regression use cases and safety rules, with traceability records, and versioned grayscale is launched after passing the safety gate.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Task execution track + Human feedback\"] --&gt; B[\"experience buffer&lt;br/&gt;episodes · traces · failures\"]\n    B --&gt; C[\"Reflect and evaluate&lt;br/&gt;Score for success or failure · failure attribution · Consistency check\"]\n    C --&gt; D[\"candidate update&lt;br/&gt;memory / prompt / tool strategy / task map / Skills\"]\n    D --&gt; E{\"safety gate&lt;br/&gt;Offline regression + safety rules\"}\n    E -- \"failed\" --&gt; F[\"Reject and leave traces, do not enter runtime\"]\n    E -- \"Pass\" --&gt; G[\"Versioned, traceable staged rollout\"]\n    G --&gt; H[\"Deploy into skill runtime\"]\n    G --&gt; I[\"Keep one-click rollback to the previous version\"]\n    H -.-&gt; A\n</code></pre>\n<p>Note that the two nodes <strong>F and I in this picture are the real design proposition</strong>: any candidate update has a “rejected and left traces” path, and any online version has a “rollback” path. The paper calls this boundary what is necessary to keep long-running robots reproducible and auditable.</p>\n<h4 id=\"27-端到端从图像到工单的证据链\">2.7 End-to-end: Evidence chain from image to work order</h4>\n<p>The inspection and reasoning pipeline is organized according to “observation → interpretation → verification → reporting → review”. OpenClaw selects the image associated with the waypoint, binds the pose, timestamp, waypoint, task ID, applicable inspection strategy, and then calls Qwen3-VL; the returned description is parsed into a <strong>constrained event schema</strong> (hazard category, severity, evidence, location, recommended disposal action). The target categories are divided into two groups - safety category (stacks around the equipment room, occupied fire escapes, water accumulation on the ground, exposed cables) and sanitation category (overflowing trash cans, stains on the ground, scattered garbage and leaves, abnormal accumulation in public areas).</p>\n<p>Only events that pass schema verification will enter the operation pipeline. The system retains the original image, original response of the model, parsed fields, and delivery status. It generates a structured report after labeling the location and area, and routes it to the responsible person for review and dispatch via the DingTalk/Feishu adapter. <strong>Manual corrections are written back in the form of tagged feedback instead of silently overwriting the original results</strong> - which not only ensures that subsequent evaluations and memory updates are informed, but also maintains auditable and replayable records. This design also keeps multimodal reasoning out of safety-critical motion loops.</p>\n<h4 id=\"28-关于训练目标\">2.8 About “Training Objectives”</h4>\n<p>There is no training link in this article. The entire system is assembled from ready-made components. There are no learnable parameters and no loss functions. The only formula in the whole article is the definition of word error rate in the speech experiment:</p>\n\n\\[\\text{WER} = (S + D + I) / N\\]\n\n<p>Here, $S$, $D$, and $I$ are the number of substitution, deletion, and insertion errors respectively, and $N$ is the total number of reference words.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-7\">3. Results and findings</h3>\n<p>System-level measurements deployed in a real residential complex (Table 1):</p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Subsystem</th>\n<th>indicator</th>\n<th>result</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Navigation and Movement</td>\n<td>Task execution</td>\n<td>Waypoint accessibility rate</td>\n<td>100%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Fast-LIO2</td>\n<td>Outdoor positioning error</td>\n<td>&lt; 10 cm</td>\n</tr>\n<tr>\n<td> </td>\n<td>EGO-Planner</td>\n<td>Obstacle response delay</td>\n<td>&lt; 200 ms</td>\n</tr>\n<tr>\n<td>Semantic inspection</td>\n<td>Qwen3-VL</td>\n<td>Garbage overflow detection rate</td>\n<td>95%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Fire exit occupancy detection rate</td>\n<td>95%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Lane occupancy detection rate</td>\n<td>90%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Ground water detection rate</td>\n<td>88%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Damage detection rate of public facilities</td>\n<td>85%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Inspection reasoning</td>\n<td>Hidden danger false alarm rate/missed detection rate</td>\n<td>All &lt; 5%</td>\n</tr>\n<tr>\n<td>Operation closed-loop</td>\n<td>DingTalk/Feishu Adapter</td>\n<td>Alarm delivery success rate</td>\n<td>99%</td>\n</tr>\n<tr>\n<td> </td>\n<td>HROS report</td>\n<td>Structured report generation accuracy</td>\n<td>99%</td>\n</tr>\n<tr>\n<td>Live operation</td>\n<td>Robot platform</td>\n<td>Continuous battery life</td>\n<td>&gt; 3 h</td>\n</tr>\n<tr>\n<td> </td>\n<td>end-to-end tasks</td>\n<td>Full coverage of single inspection time</td>\n<td>≤ 60 min</td>\n</tr>\n</tbody>\n</table>\n<p>A few points worth noting:</p>\n<ul>\n<li>The detection rate of <strong>decreases regularly with visual categories.</strong>: 95% of garbage overflows and fire escape passages are occupied, and only 85% of public facilities are damaged. The author attributes the diversity of visual forms in the category of facility damage to be much greater than the first two categories - this is consistent with the argument that “hazards are defined by spatial and operational context, rather than just by the identity of the object.”</li>\n<li><strong>has a battery life of 3 hours. For a single mission of 60 minutes, there is room for multiple rounds of</strong>, which is a prerequisite for scheduling.</li>\n<li>The most important thing about <strong>is the part without numbers</strong>: Paper §5.6 wrote a complete controlled experimental protocol for voice interaction, hierarchical memory, and security door self-evolution (WER, grounding intention accuracy, confirmation accuracy, P95 end-to-end delay; Recall@5, spatiotemporal grounding accuracy, context token Reduction rate, stale memory error rate; change in task success rate, regression rate, safety rule violation rate, safety gate rejection rate, rollback success rate, <strong>requires a safety gate escape rate of zero (</strong>), but there are no numbers in these three blocks in Table 1. The original text states that “the values need to be reported after the corresponding controlled test is completed.” In other words, the cognitive runtime of <strong>HROS is currently an architectural proposal and a set of evaluation designs. What is demonstrated is the layer of classic navigation and VLM inspection pipeline</strong> below it.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-7\">4. Limitations</h3>\n<p>The author listed four items: long-term map maintenance (parking patterns, construction, vegetation, and seasonal changes require incremental mapping, change detection, and multi-session map management), open world hazard identification (a wider hazard classification system requires more diverse annotation data, calibration confidence, and ambiguity processing), and agent evaluation and security (memory and self-evolution) Mechanisms need to be specifically benchmarked to measure retrieval quality, adaptation benefits, regression risk and rollback reliability before we can talk about releasing automatic updates in production environments), human-machine collaboration (ASR robustness under outdoor noise, confirmation design of safety-critical instructions, operator load, integration with access control broadcast alarm digital twins).</p>\n<p>One additional sentence that should be taken into account when reading this article: it is a <strong>system and architecture paper</strong>. Navigation and perception all use off-the-shelf open source software. The real novelty lies in the design of inter-layer boundaries and governance processes; and the three most promising pieces of this design (voice grounding, layered memory, and safety gate self-evolution) are still in the protocol stage, and no comparable experimental evidence has yet been provided.</p>\n<hr/>\n<h1 id=\"参考资料\">References</h1>\n<h2 id=\"论文引用\">Paper citations</h2>\n<ol>\n<li><strong>HoloAgent-0</strong> (2026). HoloAgent: A Closed-Loop Embodied Agent Operating System with Hierarchical Spatial Memory. arXiv: <a href=\"https://arxiv.org/abs/2606.23565\" rel=\"noopener noreferrer\" target=\"_blank\">2606.23565</a> · Code: <a href=\"https://github.com/HorizonRobotics/HoloAgent\" rel=\"noopener noreferrer\" target=\"_blank\">HorizonRobotics/HoloAgent</a></li>\n<li><strong>Pigey</strong> (2026). Addressing the Orchestration Gap in Generalist Robots via Physical Agency. arXiv: <a href=\"https://arxiv.org/abs/2607.21725\" rel=\"noopener noreferrer\" target=\"_blank\">2607.21725</a></li>\n<li><strong>Thea</strong> (2026). Towards the Harness of Embodied Agents. arXiv: <a href=\"https://arxiv.org/abs/2608.11246\" rel=\"noopener noreferrer\" target=\"_blank\">2608.11246</a> · Code: <a href=\"https://github.com/EIT-HAI/Thea\" rel=\"noopener noreferrer\" target=\"_blank\">EIT-HAI/Thea</a> · Project Page: <a href=\"https://eit-hai.github.io/thea\" rel=\"noopener noreferrer\" target=\"_blank\">eit-hai.github.io/thea</a></li>\n<li><strong>Zetta</strong> (2026). An Efficient Closed-Loop Embodied Harness for Self-Evolving Physical Intelligence. arXiv: <a href=\"https://arxiv.org/abs/2608.16590\" rel=\"noopener noreferrer\" target=\"_blank\">2608.16590</a> · Project Page: <a href=\"https://air-embodied-brain.github.io/zetta\" rel=\"noopener noreferrer\" target=\"_blank\">air-embodied-brain.github.io/zetta</a></li>\n<li><strong>Show-Harness</strong> (2026). Show-Harness: Just a VLM Agent Can Play Robots. arXiv: <a href=\"https://arxiv.org/abs/2609.10522\" rel=\"noopener noreferrer\" target=\"_blank\">2609.10522</a> · Project Page: <a href=\"https://showlab.github.io/Show-Harness\" rel=\"noopener noreferrer\" target=\"_blank\">showlab.github.io/Show-Harness</a></li>\n<li><strong>SPACE</strong> (2026). Act More, Decide Less: Skill-Guided Adaptive Action Chunking for Long-Horizon LLM Agents. arXiv: <a href=\"https://arxiv.org/abs/2609.02042\" rel=\"noopener noreferrer\" target=\"_blank\">2609.02042</a></li>\n<li>\n<p><strong>ABot-AgentOS</strong> (2026). Universal robot Agent operating system and lifelong multi-modal memory system for embodied intelligence. arXiv: <a href=\"https://arxiv.org/abs/2607.10350\" rel=\"noopener noreferrer\" target=\"_blank\">2607.10350</a> · Project Page: <a href=\"https://amap-cvlab.github.io/ABot-AgentOS\" rel=\"noopener noreferrer\" target=\"_blank\">ABot-AgentOS</a></p>\n</li>\n<li><strong>Harness Robotic OS</strong> (2026). Upgrade the quadruped inspection from “navigation stack” to “embodied agent runtime”. arXiv: <a href=\"https://arxiv.org/abs/2609.11225\" rel=\"noopener noreferrer\" target=\"_blank\">2609.11225</a></li>\n</ol>\n\n", "styles": ["\n  /* 回到顶部按钮样式 */\n  #backToTop {\n    position: fixed;\n    bottom: 2rem;\n    right: 2rem;\n    width: 3rem;\n    height: 3rem;\n    background: var(--theme-color, #a4a8b1);\n    color: white;\n    border: none;\n    border-radius: 50%;\n    cursor: pointer;\n    opacity: 0;\n    transform: translateY(100%);\n    transition: all 0.3s ease;\n    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 999; /* 确保在其它元素之上 */\n  }\n  \n  #backToTop.show {\n    opacity: 1;\n    transform: translateY(0);\n  }\n  \n  @media (hover: hover) {\n    #backToTop:hover {\n      background: var(--theme-hover-color, #a4a8b1);\n      transform: translateY(0) scale(1.1);\n    }\n  }\n  "], "articleClasses": ["posts", "paper-figures"], "removedImages": 43};
window.BLOG_ARTICLE_FEATURES = window.BLOG_ARTICLE_FEATURES || {};
window.BLOG_ARTICLE_FEATURES["en/embodied-agent-papers"] = function(entry) {
function localId(id) { return entry.querySelector("#"+id); }

  var TAG_MAP = [
    { m: 'Harness Robotic OS', t: ['AgentOS', 'Harness', 'Closed-loop systems', 'Spatial memory', 'self-evolution', 'Real-robot deployment'] },
    { m: 'HoloAgent-0', t: ['AgentOS', 'Closed-loop systems', 'Typed actions', 'Spatial memory', 'Scene graph', '3D semantics', 'Real-robot deployment', 'Multi-machine collaboration'] },
    { m: 'Pigey',       t: ['Closed-loop systems', 'Embodied manipulation', 'Fast and slow dual system', 'Real-robot deployment', 'TAMP', 'VLA', 'double check', 'Zero fine-tuning'] },
    { m: 'Thea',        t: ['Harness', 'Closed-loop systems', 'Scene graph', 'Exit-code evaluation', 'Real-robot deployment', 'Cross-embodiment', 'Active exploration', 'Embodied manipulation'] },
    { m: 'Zetta',       t: ['Harness', 'Closed-loop systems', 'self-evolution', 'High-frequency judge', 'Exception recovery', 'Embodied manipulation', 'High-throughput infrastructure'] },
    { m: 'Show-Harness', t: ['Harness', 'Closed-loop systems', 'Embodied manipulation', 'Typed actions', 'Real-robot deployment', 'Cross-embodiment', 'VLA', 'Zero fine-tuning'] },
    { m: 'SPACE',       t: ['action chunking', 'reinforcement learning', 'Skill induction', 'Long-horizon tasks'] },
    { m: 'ABot-AgentOS', t: ['AgentOS', 'Harness', 'Closed-loop systems', 'Topological graph', 'Spatial memory', 'self-evolution', 'Real-robot deployment'] },
  ];

  var ALL_TAGS = ['Closed-loop systems', 'Harness', 'AgentOS', 'Embodied manipulation', 'Scene graph', 'Topological graph', 'Real-robot deployment', 'Fast and slow dual system', 'Typed actions', 'Spatial memory', '3D semantics', 'Multi-machine collaboration', 'TAMP', 'VLA', 'double check', 'Exit-code evaluation', 'self-evolution', 'High-frequency judge', 'Cross-embodiment', 'Active exploration', 'Zero fine-tuning', 'action chunking', 'reinforcement learning', 'Skill induction', 'Long-horizon tasks'];

  var activeTags = [];
  var resultsPanel = null;

  function getTagsForTitle(text) {
    for (var i = 0; i < TAG_MAP.length; i++) {
      if (text.indexOf(TAG_MAP[i].m) !== -1) return TAG_MAP[i].t;
    }
    return null;
  }

  function toggleTag(tag) {
    var idx = activeTags.indexOf(tag);
    if (idx === -1) activeTags.push(tag);
    else activeTags.splice(idx, 1);
    updateFilter();
  }

  function sectionMatches(sectionTags) {
    return activeTags.every(function (t) {
      return sectionTags.indexOf(t) !== -1;
    });
  }

  function updateFilter() {
    var sections = entry.querySelectorAll('.paper-section');
    var bar = localId('paper-filter-bar');
    if (!bar) return;
    var matchedSections = [];

    bar.querySelectorAll('.filter-btn').forEach(function (btn) {
      var t = btn.getAttribute('data-tag');
      if (t === '__all__') {
        btn.classList.toggle('active', activeTags.length === 0);
        btn.setAttribute('aria-pressed', activeTags.length === 0 ? 'true' : 'false');
      } else {
        var active = activeTags.indexOf(t) !== -1;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
      }
    });

    sections.forEach(function (s) {
      var sectionTags = s.getAttribute('data-tags').split(',');
      var visible = activeTags.length === 0 || sectionMatches(sectionTags);
      s.classList.toggle('hidden', !visible);
      if (visible) matchedSections.push(s);
    });

    var totalAll = sections.length;
    var matchedAll = matchedSections.length;
    var countEl = bar.querySelector('.filter-count');
    if (countEl) {
      countEl.textContent = activeTags.length === 0
        ? totalAll + ' papers'
        : matchedAll + ' / ' + totalAll + ' papers';
    }

    updateResultsPanel(matchedSections);
  }

  function updateResultsPanel(matchedSections) {
    if (!resultsPanel) return;
    if (activeTags.length === 0) {
      resultsPanel.style.display = 'none';
      return;
    }
    resultsPanel.style.display = 'block';
    var list = resultsPanel.querySelector('.results-list');
    list.innerHTML = '';

    matchedSections.forEach(function (s) {
      var h2 = s.querySelector('h2');
      if (!h2) return;
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + h2.id; a.dataset.jump = h2.id;
      a.textContent = h2.textContent.trim().replace(/#$/, '').trim();
      li.appendChild(a);
      list.appendChild(li);
    });
  }

  function buildFilterBar() {
    var bar = localId('paper-filter-bar');
    if (!bar) return;

    var label = document.createElement('span');
    label.className = 'filter-label';
    label.textContent = 'Filter:';
    bar.appendChild(label);

    var allBtn = document.createElement('button');
    allBtn.className = 'filter-btn active';
    allBtn.type = 'button';
    allBtn.setAttribute('aria-label', 'Clear paper filter');
    allBtn.setAttribute('aria-pressed', 'true');
    allBtn.setAttribute('data-tag', '__all__');
    allBtn.textContent = 'All';
    allBtn.addEventListener('click', function () {
      activeTags = [];
      updateFilter();
    });
    bar.appendChild(allBtn);

    ALL_TAGS.forEach(function (tag) {
      var btn = document.createElement('button');
      btn.className = 'filter-btn';
      btn.type = 'button';
      btn.setAttribute('aria-pressed', 'false');
      btn.setAttribute('data-tag', tag);
      btn.textContent = tag;
      btn.addEventListener('click', function () { toggleTag(tag); });
      bar.appendChild(btn);
    });

    var count = document.createElement('span');
    count.className = 'filter-count';
    count.setAttribute('aria-live', 'polite');
    bar.appendChild(count);

    resultsPanel = document.createElement('div');
    resultsPanel.className = 'paper-filter-results';
    resultsPanel.setAttribute('aria-live', 'polite');
    resultsPanel.style.display = 'none';
    var rLabel = document.createElement('span');
    rLabel.className = 'results-label';
    rLabel.textContent = 'Matching papers:';
    var rList = document.createElement('ul');
    rList.className = 'results-list';
    resultsPanel.appendChild(rLabel);
    resultsPanel.appendChild(rList);
    bar.insertAdjacentElement('afterend', resultsPanel);
  }

  function wrapSections() {

    if (!entry) return;

    var children = Array.from(entry.childNodes);
    var newChildren = [];
    var wrapper = null;

    children.forEach(function (node) {
      var isEl = node.nodeType === 1;
      var tagName = isEl ? node.tagName : null;

      if (tagName === 'H1') {
        if (wrapper) { newChildren.push(wrapper); wrapper = null; }
        newChildren.push(node);
      } else if (tagName === 'H2') {
        if (wrapper) { newChildren.push(wrapper); wrapper = null; }
        var paperTags = getTagsForTitle(node.textContent);
        if (paperTags) {
          wrapper = document.createElement('div');
          wrapper.className = 'paper-section';
          wrapper.setAttribute('data-tags', paperTags.join(','));
          wrapper.appendChild(node);
          var row = document.createElement('div');
          row.className = 'paper-tags-row';
          paperTags.forEach(function (t) {
            var span = document.createElement('span');
            span.className = 'paper-tag';
            span.setAttribute('role', 'button');
            span.setAttribute('tabindex', '0');
            span.textContent = t;
            span.addEventListener('click', function () { toggleTag(t); });
            span.addEventListener('keydown', function (event) {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                toggleTag(t);
              }
            });
            row.appendChild(span);
          });
          wrapper.appendChild(row);
        } else {
          newChildren.push(node);
        }
      } else {
        if (wrapper) wrapper.appendChild(node);
        else newChildren.push(node);
      }
    });

    if (wrapper) newChildren.push(wrapper);

    while (entry.firstChild) entry.removeChild(entry.firstChild);
    newChildren.forEach(function (n) { entry.appendChild(n); });
  }

  wrapSections(); buildFilterBar(); updateFilter();

};
